    ///   [`delegate_call`].
    ///
    /// [`delegate_call`]: stylus_sdk::call::delegate_call
    pub fn not_delegated(&self) -> Result<(), Error> {
        if self.is_logic() {
            Ok(())
        } else {
            Err(Error::UnauthorizedCallContext(UUPSUnauthorizedCallContext {}))
        }
    }
}

