    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn owner(&self) -> Address;

    /// Returns the address of the pending owner.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn pending_owner(&self) -> Address;

