                ownable::OwnableUnauthorizedAccount { account: sender },
            ));
        }
        self._transfer_ownership(sender);
        Ok(())
    }

    fn renounce_ownership(&mut self) -> Result<(), Self::Error> {
        self.ownable.only_owner()?;
        self._transfer_ownership(Address::ZERO);

