    fn average(self, rhs: Self) -> Self {
        // `(a + b) / 2` can overflow, so instead we compute
        // `(2 * (a & b) + (a ^ b)) / 2`.
        //
        // `a ^ b` computes the sum without carries while `2 * (a & b)` singles
