    pub struct Erc1967 {
        address: StorageAddress,
    }

    #[public]
    impl Erc1967 {
        fn get_implementation(&self) -> Address {
            StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).get()
        }

