    ///   `spender`'s allowance.
    fn allowance(
        &self,
        token: Address,
        spender: Address,
    ) -> Result<U256, Error> {
        if !Address::has_code(&token) {
            return Err(SafeErc20FailedOperation { token }.into());
        }

