    #![allow(clippy::unused_self)]

    use alloy_primitives::{uint, Address, U256};
    use crate::test_support::{test_address, TestContract as TestVMContract};
    use stylus_sdk::storage::StorageAddress;

    use super::*;

    const IMPLEMENTATION_SLOT: U256 = uint!(12345_U256);

    #[storage]
    #[entrypoint]
    pub struct Erc1967 {
        address: StorageAddress,
    }

    #[public]
    impl Erc1967 {
        fn get_implementation(&self) -> Address {
            StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).get()
        }

        fn set_implementation(&self, new_implementation: Address) {
            StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT)
                .set(new_implementation);
        }

        fn get_address(&self) -> Address {
            self.address.get()
        }

        fn set_address(&mut self, new_address: Address) {
            self.address.set(new_address);
        }

        fn get_address_at_zero_slot(&self) -> Address {
            StorageSlot::get_slot::<StorageAddress>(U256::ZERO).get()
        }

        fn set_address_at_zero_slot(&mut self, new_address: Address) {
            StorageSlot::get_slot::<StorageAddress>(U256::ZERO)
                .set(new_address);
        }
    }

    #[test]
    fn test_storage_slot() {
        let contract = TestVMContract::<Erc1967>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));
        let impl_address = test_address(stringify!(impl_address));

        let implementation = contract.sender(alice).get_implementation();
        assert_eq!(implementation, Address::ZERO);

        contract.sender(alice).set_implementation(impl_address);

        let implementation = contract.sender(alice).get_implementation();
        assert_eq!(implementation, impl_address);
        let address = contract.sender(alice).get_address_at_zero_slot();
        assert_eq!(address, Address::ZERO);
        let address = contract.sender(alice).get_address();
        assert_eq!(address, Address::ZERO);

        contract.sender(alice).set_address(impl_address);

        let implementation = contract.sender(alice).get_implementation();
        assert_eq!(implementation, impl_address);
        let address = contract.sender(alice).get_address_at_zero_slot();
        assert_eq!(address, impl_address);
        let address = contract.sender(alice).get_address();
        assert_eq!(address, impl_address);

        contract.sender(alice).set_address_at_zero_slot(alice);

        let implementation = contract.sender(alice).get_implementation();
        assert_eq!(implementation, impl_address);
        let address = contract.sender(alice).get_address_at_zero_slot();
        assert_eq!(address, alice);
        let address = contract.sender(alice).get_address();
        assert_eq!(address, alice);
    }
}
//! A collection of utilities for working with [`Address`].

use alloc::vec::Vec;

use alloy_primitives::Address;
pub use sol::*;
use stylus_sdk::{
    call, host::VM,
    prelude::*,
};

#[cfg_attr(coverage_nightly, coverage(off))]
mod sol {
    use alloy_sol_macro::sol;

    sol! {
        /// There's no code at `target` (it is not a contract).
        ///
        /// * `target` - Address of the target contract.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error AddressEmptyCode(address target);

        /// A call to an address target failed. The target may have reverted
        /// without a revert reason.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error FailedCall();

        /// A call to an address target failed. The target may have reverted
        /// with a reason.
        ///
        /// * `reason` - The revert reason that was returned by the call.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error FailedCallWithReason(bytes reason);
    }
}

/// An [`AddressUtils`] error.
#[derive(SolidityError, Debug)]
pub enum Error {
    /// There's no code at `target` (it is not a contract).
    EmptyCode(AddressEmptyCode),
    /// A call to an address target failed. The target may have reverted
    /// without a revert reason.
    FailedCall(FailedCall),
    /// A call to an address target failed. The target may have reverted
    /// with a reason.
    FailedCallWithReason(FailedCallWithReason),
}

impl MethodError for Error {
    fn encode(self) -> alloc::vec::Vec<u8> {
        self.into()
    }
}

/// A collection of utilities for working with [`Address`].
pub struct AddressUtils;

impl AddressUtils {
    /// Performs a delegate call to `target` with the given `data`.
    ///
    /// # Arguments
    ///
    /// * `context` - Mutable access to the contract's state.
    /// * `target` - The address of the target contract.
    /// * `data` - The data to pass to the target contract.
    ///
    /// # Errors
    ///
    /// * [`Error::FailedCall`] - If the call to the target contract fails
    ///   without a revert reason.
    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
    ///   fails with a revert reason or if the call fails for any other reason.
    /// * [`Error::EmptyCode`] - If the target contract has no code.
    pub fn function_delegate_call(
        context: &mut (impl TopLevelStorage + HostAccess<Host = VM>),
        target: Address,
        data: &[u8],
    ) -> Result<Vec<u8>, Error> {
        let vm = context.vm().clone();
        let result = unsafe {
            call::delegate_call(&vm, Call::new_mutating(context), target, data)
        };
        Self::verify_call_result_from_target(context, target, result)
    }

    // TODO: Support more result types out of the box (e.g. `U256`, `U160`,
    // `String`, etc.).
    /// Helper function to verify that a low level call to smart-contract was
    /// successful.
    ///
    /// Reverts if the target was not a contract or if the call fails for any
    /// other reason. Bubbles up the revert reason (falling back to
    /// [`Error::FailedCall`]) in case of an unsuccessful call.
    ///
    /// # Arguments
    ///
    /// * `target` - The address of the target contract.
    /// * `result` - The result of the call.
    ///
    /// # Errors
    ///
    /// * [`Error::EmptyCode`] - If the target contract has no code.
    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
    ///   fails with a revert reason or if the call fails for any other reason.
    /// * [`Error::FailedCall`] - If the call to the target contract fails
    ///   without a revert reason.
    pub fn verify_call_result_from_target<T: AsRef<[u8]>>(
        context: &impl HostAccess<Host = VM>,
        target: Address,
        result: Result<T, stylus_sdk::stylus_core::calls::errors::Error>,
    ) -> Result<T, Error> {
        match result {
            Ok(returndata) => {
                if returndata.as_ref().is_empty()
                    && context.vm().code_size(target) == 0
                {
                    return Err(AddressEmptyCode { target }.into());
                }
                Ok(returndata)
            }
            Err(e) => Err(Self::revert(e)),
        }
    }
}

impl AddressUtils {
    /// Reverts with `error` if revert reason exists. Otherwise reverts with
    /// [`Error::FailedCall`].
    ///
    /// This behavior is aligned with Solidity implementation of
    /// [Address.sol].
    ///
    /// [Address.sol]: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/utils/Address.sol
    fn revert(error: stylus_sdk::stylus_core::calls::errors::Error) -> Error {
        match &error {
            stylus_sdk::stylus_core::calls::errors::Error::Revert(data)
                if data.is_empty() =>
            {
                FailedCall {}.into()
            }
            _ => FailedCallWithReason { reason: error.encode().into() }.into(),
        }
    }
}

use stylus_sdk::prelude::errors::MethodError;
//! [EIP-712](https://eips.ethereum.org/EIPS/eip-712) is a standard for hashing
//! and signing typed structured data.
//!
//! The implementation of the domain separator was designed to be as efficient
//! as possible while still properly updating the chain id to protect against
//! replay attacks on an eventual fork of the chain.
//!
//! NOTE: This contract implements the version of the encoding known as "v4", as
//! implemented by the JSON RPC method [`eth_signTypedDataV4`] in `MetaMask`.
//!
//! [`eth_signTypedDataV4`]: https://docs.metamask.io/guide/signing-data.html

use alloc::{borrow::ToOwned, string::String, vec::Vec};

use alloy_primitives::{keccak256, Address, B256, U256};
use alloy_sol_types::{sol, SolType};
use stylus_sdk::prelude::*;

/// Keccak-256 hash of the EIP-712 domain separator type string.
const TYPE_HASH: [u8; 32] =
    keccak_const::Keccak256::new()
        .update(b"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
        .finalize();

/// Field for the domain separator.
const FIELDS: [u8; 1] = [0x0f];

/// Salt for the domain separator.
const SALT: [u8; 32] = [0u8; 32];

/// Prefix for ERC-191 version with `0x01`.
const TYPED_DATA_PREFIX: [u8; 2] = [0x19, 0x01];

/// Tuple for the domain separator.
type DomainSeparatorTuple = sol! {
    tuple(bytes32, bytes32, bytes32, uint256, address)
};

/// Returns the keccak256 digest of an EIP-712 typed data (ERC-191 version
/// `0x01`).
///
/// The digest is calculated from a `domain_separator` and a `struct_hash`, by
/// prefixing them with `[TYPED_DATA_PREFIX]` and hashing the result. It
/// corresponds to the hash signed by the [eth_signTypedData] JSON-RPC method as
/// part of EIP-712.
///
/// [eth_signTypedData]: https://eips.ethereum.org/EIPS/eip-712
#[must_use]
pub fn to_typed_data_hash(
    domain_separator: &[u8; 32],
    struct_hash: &[u8; 32],
) -> B256 {
    let mut preimage = [0u8; 66];
    preimage[..2].copy_from_slice(&TYPED_DATA_PREFIX);
    preimage[2..34].copy_from_slice(domain_separator);
    preimage[34..].copy_from_slice(struct_hash);
    keccak256(preimage)
}

/// EIP-712 Contract interface.
pub trait IEip712: HostAccess {
    /// Immutable name of EIP-712 instance.
    const NAME: &'static str;
    /// Hashed name of EIP-712 instance.
    const HASHED_NAME: [u8; 32] =
        keccak_const::Keccak256::new().update(Self::NAME.as_bytes()).finalize();

    /// Immutable version of EIP-712 instance.
    const VERSION: &'static str;
    /// Hashed version of EIP-712 instance.
    const HASHED_VERSION: [u8; 32] = keccak_const::Keccak256::new()
        .update(Self::VERSION.as_bytes())
        .finalize();

    /// Returns chain id.
    #[must_use]
    fn chain_id(&self) -> U256 {
        U256::from(self.vm().chain_id())
    }

    /// Returns the contract's address.
    #[must_use]
    fn contract_address(&self) -> Address {
        self.vm().contract_address()
    }

    /// Returns the fields and values that describe the domain separator used by
    /// this contract for EIP-712 signature.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn eip712_domain(
        &self,
    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
        (
            FIELDS,
            Self::NAME.to_owned(),
            Self::VERSION.to_owned(),
            self.chain_id(),
            self.contract_address(),
            SALT,
            Vec::new(),
        )
    }

    /// Returns the domain separator for the current chain.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn domain_separator_v4(&self) -> B256 {
        let encoded = DomainSeparatorTuple::abi_encode(&(
            TYPE_HASH,
            Self::HASHED_NAME,
            Self::HASHED_VERSION,
            self.chain_id(),
            self.contract_address(),
        ));

        keccak256(encoded)
    }

    /// Given an already [hashed struct], this function returns the hash of the
    /// fully encoded EIP-712 message for this domain.
    ///
    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn hash_typed_data_v4(&self, struct_hash: B256) -> B256 {
        let domain_separator = self.domain_separator_v4();
        to_typed_data_hash(&domain_separator, &struct_hash)
    }
}

#[cfg(test)]
mod tests {
