    /// * If multiplication or division operations overflow during conversion.
    pub fn _convert_to_shares(
        &self,
        assets: U256,
        rounding: Rounding,
        erc20: &Erc20,
    ) -> Result<U256, Error> {
        let total_supply = erc20.total_supply();

        let multiplier = total_supply
            .checked_add(
