    ///
    /// * If decimal offset calculation overflows.
    /// * If multiplication or division operations overflow.
    pub fn _convert_to_assets(
        &self,
        shares: U256,
        rounding: Rounding,
        erc20: &Erc20,
    ) -> Result<U256, Error> {
