    pub fn _grant_role(
        &mut self,
        role: B256,
        account: Address,
        access_control: &mut AccessControl,
    ) -> bool {
        let granted = access_control._grant_role(role, account);

        if granted {
            self.role_members.setter(role).add(account);
        }

        granted
    }

