    /// * If scaled, total allocation (mid calculation) exceeds [`U256::MAX`].
    #[selector(name = "vestedAmount")]
    fn vested_amount_erc20(
        &mut self,
        token: Address,
        timestamp: u64,
    ) -> Result<U256, Self::Error>;
