//! ERC-721 token with storage-based token URI management.
//!
//! It also implements IERC4096, which is an ERC-721 Metadata Update Extension.
use alloc::{string::String, vec, vec::Vec};

use alloy_primitives::U256;
pub use sol::*;
use stylus_sdk::{

    prelude::*,
    storage::{StorageMap, StorageString},
};

use crate::token::erc721::{
    self,
    extensions::{Erc721Metadata, IErc721Metadata},
    IErc721,
};

#[cfg_attr(coverage_nightly, coverage(off))]
mod sol {
    use alloy_sol_macro::sol;

    sol! {
        /// This event gets emitted when the metadata of a token is changed.
        ///
        /// The event comes from IERC4096.
        #[derive(Debug)]
        #[allow(missing_docs)]
        event MetadataUpdate(uint256 token_id);

        /// This event gets emitted when the metadata of a range of tokens
        /// is changed.
        ///
        /// The event comes from IERC4096.
        #[derive(Debug)]
        #[allow(missing_docs)]
        event BatchMetadataUpdate(uint256 from_token_id, uint256 to_token_id);
    }
}

/// State of an [`Erc721UriStorage`] contract.
#[storage]
pub struct Erc721UriStorage {
    /// Optional mapping for token URIs.
    pub token_uris: StorageMap<U256, StorageString>,
}

/// Interface of an optional extension ERC-721 token providing storage based
/// token URI management.
pub trait IErc721UriStorage: IErc721Metadata {}

impl Erc721UriStorage {
    /// Sets `token_uri` as the token URI of `token_id`.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `token_id` - Id of a token.
    /// * `token_uri` - URI for the token.
    ///
    /// # Events
    ///
    /// * [`MetadataUpdate`].
    pub fn _set_token_uri(&mut self, token_id: U256, token_uri: String) {
        self.token_uris.setter(token_id).set_str(token_uri);
        self.vm().log(MetadataUpdate { token_id });
    }

    /// Check [`IErc721Metadata::token_uri()`] for more details.
    #[allow(clippy::missing_errors_doc)]
    pub fn token_uri(
        &self,
        token_id: U256,
        erc721: &impl IErc721<Error = erc721::Error>,
        metadata: &Erc721Metadata,
    ) -> Result<String, erc721::Error> {
        erc721.owner_of(token_id)?;

        let token_uri = self.token_uris.getter(token_id).get_string();
        let base = metadata.base_uri();

        // If there is no base URI, return the token URI.
        if base.is_empty() {
            return Ok(token_uri);
        }

        // If both are set, concatenate the `base_uri` and `token_uri`.
        let uri = if token_uri.is_empty() {
            metadata.token_uri(token_id, erc721)?
        } else {
            base + &token_uri
        };

        Ok(uri)
    }
}

#[cfg(test)]
mod tests {
    use alloy_primitives::{uint, Address};
    use crate::test_support::{test_address, TestContract as TestVMContract};
    use stylus_sdk::prelude::*;

    use super::*;
    use crate::{
        token::erc721::{self, extensions::Erc721Metadata, Erc721},
        utils::introspection::erc165::IErc165,
    };
    const TOKEN_ID: U256 = uint!(1_U256);
    use alloy_primitives::aliases::B32;

    #[storage]
    struct Erc721MetadataExample {
        pub erc721: Erc721,
        pub metadata: Erc721Metadata,
        pub uri_storage: Erc721UriStorage,
    }

    #[public]
    #[implements(IErc721Metadata<Error = erc721::Error>, IErc165)]
    impl Erc721MetadataExample {
        #[constructor]
        fn constructor(&mut self, name: String, symbol: String) {
            self.metadata.constructor(name, symbol);
        }

        #[selector(name = "setTokenURI")]
        fn set_token_uri(&mut self, token_id: U256, token_uri: String) {
            self.uri_storage._set_token_uri(token_id, token_uri);
        }
    }

    #[public]
    impl IErc721Metadata for Erc721MetadataExample {
        type Error = erc721::Error;

        fn name(&self) -> String {
            self.metadata.name()
        }

        fn symbol(&self) -> String {
            self.metadata.symbol()
        }

        #[selector(name = "tokenURI")]
        fn token_uri(&self, token_id: U256) -> Result<String, erc721::Error> {
            self.uri_storage.token_uri(token_id, &self.erc721, &self.metadata)
        }
    }

    #[public]
    impl IErc165 for Erc721MetadataExample {
        fn supports_interface(&self, interface_id: B32) -> bool {
            <Self as IErc721Metadata>::interface_id() == interface_id
                || <Self as IErc165>::interface_id() == interface_id
        }
    }

    unsafe impl TopLevelStorage for Erc721MetadataExample {}

    #[test]
    fn interface_id() {
        let actual = <Erc721MetadataExample as IErc721Metadata>::interface_id();
        let expected: B32 = 0x5b5e139f_u32.into();
        assert_eq!(actual, expected);
    }

    #[test]
    fn supports_interface() {
        let contract = TestVMContract::<Erc721MetadataExample>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        assert!(contract.sender(alice).supports_interface(
            <Erc721MetadataExample as IErc721Metadata>::interface_id()
        ));
        assert!(contract.sender(alice).supports_interface(
            <Erc721MetadataExample as IErc165>::interface_id()
        ));

        let fake_interface_id: B32 = 0x12345678_u32.into();
        assert!(!contract.sender(alice).supports_interface(fake_interface_id));
    }
    #[test]
    fn token_uri_works() {
        let contract = TestVMContract::<Erc721MetadataExample>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        contract
            .sender(alice)
            .erc721
            ._mint(alice, TOKEN_ID)
            .expect("should mint a token for Alice");

        let token_uri = String::from("https://docs.openzeppelin.com/contracts/5.x/api/token/erc721#Erc721URIStorage");
        contract.sender(alice).set_token_uri(TOKEN_ID, token_uri.clone());

        assert_eq!(
            token_uri,
            contract
                .sender(alice)
                .token_uri(TOKEN_ID)
                .expect("should return token URI")
        );
    }
}
//! Contains generic size utilities for checkpoint storage contract.

use core::ops::{Add, Div, Mul, Sub};

use alloy_sol_types::sol_data::{IntBitCount, SupportedInt};
use stylus_sdk::{alloy_primitives::Uint, prelude::*};

/// Trait that associates types of specific size for checkpoints key and value.
pub trait Size {
    /// Type of the key in abi.
    type Key: Num;

    /// Type of the key in storage.
    type KeyStorage: for<'a> StorageType<Wraps<'a> = Self::Key>
        + Accessor<Wraps = Self::Key>;

    /// Type of the value in abi.
    type Value: Num;

    /// Type of the value in storage.
    type ValueStorage: for<'a> StorageType<Wraps<'a> = Self::Value>
        + Accessor<Wraps = Self::Value>;
}

/// Defines size of checkpoint storage contract with specific key and value
/// bits.
///
/// # Arguments
///
/// * `$name` - Identifier of the typed size.
/// * `$key_bits` - Number of bits in checkpoint's key.
/// * `$value_bits` - Number of bits in checkpoint's value.
macro_rules! define_checkpoint_size {
    ($name:ident, $key_bits:expr, $value_bits:expr) => {
        #[doc = "Size of checkpoint storage contract with"]
        #[doc = stringify!($key_bits)]
        #[doc = "bit key and "]
        #[doc = stringify!($value_bits)]
        #[doc = "bit value."]
        pub struct $name;

        impl Size for $name {
            type Key = stylus_sdk::alloy_primitives::Uint<
                $key_bits,
                { usize::div_ceil($key_bits, 64) },
            >;
            type KeyStorage = stylus_sdk::storage::StorageUint<
                $key_bits,
                { usize::div_ceil($key_bits, 64) },
            >;
            type Value = stylus_sdk::alloy_primitives::Uint<
                $value_bits,
                { usize::div_ceil($value_bits, 64) },
            >;
            type ValueStorage = stylus_sdk::storage::StorageUint<
                $value_bits,
                { usize::div_ceil($value_bits, 64) },
            >;
        }
    };
}

define_checkpoint_size!(S160, 96, 160);
define_checkpoint_size!(S224, 32, 224);
define_checkpoint_size!(S208, 48, 208);

/// Abstracts number inside the checkpoint contract.
pub trait Num: Add + Sub + Mul + Div + Ord + Sized + Copy {
    /// Zero value of the number.
    const ZERO: Self;
}

impl<const B: usize, const L: usize> Num for Uint<B, L> {
    const ZERO: Self = Self::ZERO;
}

/// Abstracts accessor inside the checkpoint contract.
pub trait Accessor {
    /// Type of the number associated with the storage type.
    type Wraps: Num;

    /// Gets underlying element [`Self::Wraps`] from persistent storage.
    fn get(&self) -> Self::Wraps;

    /// Sets underlying element [`Self::Wraps`] in persistent storage.
    fn set(&mut self, value: Self::Wraps);
}

impl<const B: usize, const L: usize> Accessor
    for stylus_sdk::storage::StorageUint<B, L>
where
    IntBitCount<B>: SupportedInt,
{
    type Wraps = Uint<B, L>;

    fn get(&self) -> Self::Wraps {
        self.get()
    }

    fn set(&mut self, value: Self::Wraps) {
        self.set(value);
    }
}

