573	        };
574	        let secret_key = unsafe { ptr.as_ref().unwrap() };
575	
576	        assert!(secret_key.scalar.is_zero());
577	        assert_eq!(secret_key.hash_prefix, [0u8; 32]);
578	    }
579	}
