 57	    fn eq(&self, other: &Self) -> bool {
 58	        if self.is_zero() {
 59	            return other.is_zero();
 60	        }
 61	
 62	        if other.is_zero() {
 63	            return false;
 64	        }
 65	
 66	        // Checking equality without multiplication,
 67	        // e.g. x1/z1 == x2/z2 <==> x1 * z2 == x2 * z1.
 68	        (self.x * other.z) == (other.x * self.z)
 69	            && (self.y * other.z) == (other.y * self.z)
