  1	//! This module contains an ed25519 signature implementation ([EDDSA]), that
  2	//! includes key derivation, signing, and signature verification.
  3	//!
  4	//! Api and implementation of this module resembles [curve25519-dalek] crate and
  5	//! based on `openzeppelin-crypto` primitives.
  6	//!
  7	//! [EDDSA]: https://en.wikipedia.org/wiki/EdDSA
  8	//! [curve25519-dalek]: https://github.com/dalek-cryptography/curve25519-dalek
  9	
 10	#![allow(non_snake_case)]
 11	use sha2::{digest::Digest, Sha512};
 12	use static_assertions::const_assert;
 13	use zeroize::ZeroizeOnDrop;
 14	
 15	use crate::{
 16	    arithmetic::{
 17	        uint::{U256, U512},
 18	        BigInteger,
 19	    },
