 33	/// Ed25519 scalar.
 34	pub type Scalar = Fp256<Curve25519FrParam>;
 35	
 36	/// Ed25519 scalar used for reduction sha512 hash values to `256-bit`.
 37	pub(crate) type WideScalar = Fp512<Curve25519Fr512Param>;
 38	
 39	/// Scalar field parameters for curve ed25519 with `512-bit` inner integer size.
 40	pub(crate) struct Curve25519Fr512Param;
 41	impl FpParams<LIMBS_512> for Curve25519Fr512Param {
 42	    const GENERATOR: Fp512<Self> = Fp512::from_fp(Curve25519FrParam::GENERATOR);
 43	    const MODULUS: U512 = U512::from_uint(Curve25519FrParam::MODULUS);
 44	}
