 52	/// Ed25519 secret key as defined in [RFC8032 § 5.1.5]:
 53	///
 54	/// The private key is 32 octets (256 bits, corresponding to b) of
 55	/// cryptographically secure random data.
 56	///
 57	/// [RFC8032 § 5.1.5]: https://www.rfc-editor.org/rfc/rfc8032#section-5.1.5
 58	pub type SecretKey = [u8; SECRET_KEY_LENGTH];
 59	
 60	/// The length of an ed25519 [`SecretKey`] in bytes.
 61	pub const SECRET_KEY_LENGTH: usize = 32;
 62	
 63	/// Ed25519 public key as defined in [RFC8032 § 5.1.5].
 64	///
 65	/// [RFC8032 § 5.1.5]: https://www.rfc-editor.org/rfc/rfc8032#section-5.1.5
 66	pub type PublicKey = [u8; PUBLIC_KEY_LENGTH];
 67	
 68	/// The length of an ed25519 [`PublicKey`] in bytes.
 69	pub const PUBLIC_KEY_LENGTH: usize = 32;
 70	
 71	/// The length of an Ed25519 signature in bytes.
 72	pub const SIGNATURE_LENGTH: usize = 64;
 73	
 74	/// Contains the secret scalar and domain separator used for generating
 75	/// signatures.
 76	///
 77	/// This is used internally for signing.
 78	///
 79	/// In the usual Ed25519 signing algorithm, `scalar` and `hash_prefix` are
 80	/// defined such that `scalar || hash_prefix = H(sk)` where `sk` is the signing
 81	/// key and `H` is SHA-512.
 82	///
 83	/// Instances of this secret are automatically overwritten with zeroes when they
 84	/// fall out of scope.
 85	#[derive(Clone, PartialEq, Debug, ZeroizeOnDrop)]
 86	pub(crate) struct ExpandedSecretKey {
 87	    /// The secret scalar used for signing.
 88	    pub(crate) scalar: Scalar,
 89	    /// The domain separator used when hashing the message to generate the
 90	    /// pseudorandom `r` value.
 91	    pub(crate) hash_prefix: [u8; 32],
 92	}
 93	
 94	impl ExpandedSecretKey {
 95	    /// Construct secret key [`Self`] from a byte string of any length.
 96	    ///
 97	    /// Secret key will be derived from hashed `bytes`.
 98	    pub(crate) fn from_bytes(bytes: &[u8]) -> ExpandedSecretKey {
 99	        let mut scalar_bytes = [0u8; 32];
100	        let mut hash_prefix = [0u8; 32];
101	        scalar_bytes.copy_from_slice(&bytes[00..32]);
102	        hash_prefix.copy_from_slice(&bytes[32..64]);
103	
104	        let scalar = Scalar::from_bigint(U256::from_bytes_le(&clamp_integer(
105	            scalar_bytes,
106	        )));
107	        Self { scalar, hash_prefix }
108	    }
109	}
110	
111	/// Clamps the given little-endian representation of a 32-byte integer.
112	///
113	/// Clamping the value puts it in the range:
114	/// **n ∈ 2^254 + 8\*{0, 1, 2, 3, ..., 2^251 − 1}**
115	///
116	/// # Explanation of clamping
117	///
118	/// For Curve25519, h = 8, and multiplying by 8 is the same as a binary
119	/// left-shift by 3 bits. If you take a secret scalar value between 2^251 and
120	/// 2^252 – 1 and left-shift by 3 bits, then you end up with a 255-bit number
121	/// with the most significant bit set to 1 and the least-significant three bits
122	/// set to 0.
123	///
124	/// The Curve25519 clamping operation takes **an arbitrary 256-bit random
125	/// value** and clears the most-significant bit (making it a 255-bit number),
126	/// sets the next bit, and then clears the 3 least-significant bits. In other
127	/// words, it directly creates a scalar value that is in the right form and
128	/// pre-multiplied by the cofactor.
129	///
130	/// See [clamping reference] for more details.
131	///
132	/// [clamping reference]: https://neilmadden.blog/2020/05/28/whats-the-curve25519-clamping-all-about/
133	#[must_use]
134	pub const fn clamp_integer(mut bytes: [u8; 32]) -> [u8; 32] {
135	    bytes[0] &= 0b1111_1000;
136	    bytes[31] &= 0b0111_1111;
137	    bytes[31] |= 0b0100_0000;
138	    bytes
139	}
