  1050	    ///
  1051	    /// # Arguments
  1052	    ///
  1053	    /// * `caller` - Address initiating the withdrawal.
  1054	    /// * `receiver` - Address receiving the assets.
  1055	    /// * `owner` - Address owning the shares.
  1056	    /// * `assets` - Amount of underlying tokens to transfer.
  1057	    /// * `shares` - Amount of shares to burn.
  1058	    /// * `erc20` - Write access to an [`Erc20`] contract.
  1059	    ///
  1060	    /// # Errors
  1061	    ///
  1062	    /// * [`erc20::Error::InsufficientAllowance`] - If `caller` needs allowance.
  1063	    /// * [`erc20::Error::InvalidApprover`] - If `owner` is [`Address::ZERO`].
  1064	    /// * [`erc20::Error::InsufficientBalance`] - If `owner` lacks shares.
  1065	    /// * [`safe_erc20::Error::SafeErc20FailedOperation`] - If transfer fails.
  1066	    ///
  1067	    /// # Events
  1068	    ///
  1069	    /// * [`Withdraw`]
  1070	    pub fn _withdraw(
  1071	        &mut self,
  1072	        caller: Address,
  1073	        receiver: Address,
  1074	        owner: Address,
  1075	        assets: U256,
  1076	        shares: U256,
  1077	        erc20: &mut Erc20,
  1078	    ) -> Result<(), Error> {
  1079	        if caller != owner {
  1080	            erc20._spend_allowance(owner, caller, shares)?;
  1081	        }
  1082	
  1083	        // If asset() is ERC-777, `transfer` can trigger a reentrancy AFTER the
  1084	        // transfer happens through the `tokens_received` hook. On the other
  1085	        // hand, the `tokens_to_send` hook, that is triggered before the
  1086	        // transfer, calls the vault, which is assumed not malicious.
  1087	        //
  1088	        // Conclusion: we need to do the transfer after the burn so that any
  1089	        // reentrancy would happen after the shares are burned and after the
  1090	        // assets are transferred, which is a valid state.
  1091	
  1092	        erc20._burn(owner, shares)?;
  1093	
  1094	        self.safe_erc20.safe_transfer(self.asset(), receiver, assets)?;
