   347	    /// * `&mut self` - Write access to the contract's state.
   348	    /// * `account` - The account to mint tokens to.
   349	    /// * `token_id` - A mutable reference to the Erc20 contract.
   350	    /// * `erc721` - Write access to an [`Erc721`] contract.
   351	    ///
   352	    /// # Errors
   353	    ///
   354	    /// * [`Error::Erc721FailedOperation`] - If the underlying token is not a
   355	    ///   [`Erc721`]  or the contract fails to execute the call.
   356	    /// * [`Error::IncorrectOwner`] - If the underlying token is not owned by
   357	    ///   the contract.
   358	    /// * [`Error::InvalidSender`] - If `token_id` already exists.
   359	    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
   360	    /// * [`Error::InvalidReceiver`] - If
   361	    ///   [`erc721::IErc721Receiver::on_erc721_received`] hasn't returned its
   362	    ///   interface id or returned with an error.
   363	    fn _recover(
   364	        &mut self,
   365	        account: Address,
   366	        token_id: U256,
   367	        erc721: &mut Erc721,
   368	    ) -> Result<U256, Error> {
   369	        let underlying = Erc721Interface::new(self.underlying());
   370	
   371	        let owner = underlying.owner_of(self.vm(), Call::new(), token_id).map_err(
   372	            |_| {
   373	                Error::Erc721FailedOperation(Erc721FailedOperation {
   374	                    token: self.underlying(),
   375	                })
   376	            },
   377	        )?;
   378	
   379	        let contract_address = self.vm().contract_address();
   380	        if owner != contract_address {
   381	            return Err(erc721::Error::IncorrectOwner(
   382	                erc721::ERC721IncorrectOwner {
   383	                    sender: contract_address,
   384	                    token_id,
   385	                    owner,
   386	                },
   387	            )
   388	            .into());
   389	        }
   390	
   391	        erc721._safe_mint(account, token_id, &vec![].into())?;
   392	
   393	        Ok(token_id)
   394	    }
