   573	impl VestingWallet {
   574	    /// Virtual implementation of the vesting formula. This returns the amount
   575	    /// vested, as a function of time, for an asset given its total
   576	    /// historical allocation.
   577	    ///
   578	    /// # Arguments
   579	    ///
   580	    /// * `&self` - Read access to the contract's state.
   581	    /// * `total_allocation` - Total vested amount.
   582	    /// * `timestamp` - Point in time for which to calculate the vested amount.
   583	    ///
   584	    /// # Panics
   585	    ///
   586	    /// * If scaled, total allocation (mid calculation) exceeds [`U256::MAX`].
   587	    fn vesting_schedule(&self, total_allocation: U256, timestamp: U64) -> U256 {
   588	        let timestamp = U256::from(timestamp);
   589	
   590	        if timestamp < self.start() {
   591	            U256::ZERO
   592	        } else if timestamp >= self.end() {
   593	            total_allocation
   594	        } else {
   595	            // SAFETY: `timestamp` is guaranteed to be greater than
   596	            // `self.start()` as checked by earlier bounds.
   597	            let elapsed = timestamp - self.start();
   598	
   599	            let scaled_allocation = total_allocation
   600	                .checked_mul(elapsed)
   601	                .expect("scaled allocation exceeds `U256::MAX`");
   602	
   603	            // SAFETY: `self.duration()` is non-zero. If `self.duration()` were
   604	            // zero, then `end == start`, meaning that `timestamp >= self.end()`
   605	            // and the function would have returned earlier.
   606	            scaled_allocation / self.duration()
   607	        }
   608	    }
   609	}
