199	    #[allow(clippy::missing_errors_doc)]
200	    pub fn deposit_for(
201	        &mut self,
202	        account: Address,
203	        token_ids: Vec<U256>,
204	        erc721: &mut Erc721,
205	    ) -> Result<bool, Error> {
206	        let sender = self.vm().msg_sender();
207	        let contract_address = self.vm().contract_address();
208	        let underlying = Erc721Interface::new(self.underlying());
209	        let vm = self.vm().clone();
210	
211	        for token_id in token_ids {
212	            // This is an "unsafe" transfer that doesn't call any hook on
213	            // the receiver. With [`IErc721Wrapper::underlying()`] being trusted
214	            // (by design of this contract) and no other contracts expected to
215	            // be called from there, we are safe.
216	            match underlying.transfer_from(
217	                &vm,
218	                Call::new_mutating(self),
219	                sender,
220	                contract_address,
221	                token_id,
222	            ) {
223	                Ok(()) => (),
224	                Err(e) => {
225	                    if let stylus_sdk::stylus_core::calls::errors::Error::Revert(ref reason) = e {
226	                        if !reason.is_empty() {
227	                            return Err(Error::InvalidReceiverWithReason(
228	                                erc721::InvalidReceiverWithReason {
229	                                    reason: String::from_utf8_lossy(reason)
230	                                        .to_string(),
231	                                },
232	                            ));
233	                        }
234	                    }
235	                    return Err(Error::Erc721FailedOperation(
236	                        Erc721FailedOperation { token: self.underlying() },
237	                    ));
238	                }
239	            }
240	
241	            erc721._safe_mint(account, token_id, &vec![].into())?;
242	        }
243	
244	        Ok(true)
245	    }
