129	/// Interface for the NFT Royalty Standard.
130	///
131	/// A standardized way to retrieve royalty payment information for non-fungible
132	/// tokens (NFTs) to enable universal support for royalty payments across all
133	/// NFT marketplaces and ecosystem participants.
134	#[interface_id]
135	pub trait IErc2981: IErc165 {
136	    /// Returns how much royalty is owed and to whom, based on a sale price that
137	    /// may be denominated in any unit of exchange.
138	    ///
139	    /// The royalty amount is denominated and should be paid in that same unit
140	    /// of exchange.
141	    ///
142	    /// NOTE: ERC-2981 allows setting the royalty to 100% of the price.
143	    /// In that case all the price would be sent to the royalty receiver and 0
144	    /// tokens to the seller. Contracts dealing with royalty should consider
145	    /// empty transfers.
146	    ///
147	    /// # Arguments
148	    ///
149	    /// * `&self` - Read access to the contract's state.
150	    /// * `token_id` - Id of a token.
151	    /// * `sale_price` - The sale price of the token.
152	    ///
153	    /// # Panics
154	    ///
155	    /// * If `sale_price` * `royalty_fraction` overflows.
156	    /// * If [`Erc2981::_fee_denominator()`] is zero.
157	    fn royalty_info(&self, token_id: U256, sale_price: U256)
158	        -> (Address, U256);
159	}
