171	impl IErc2981 for Erc2981 {
172	    fn royalty_info(
173	        &self,
174	        token_id: U256,
175	        sale_price: U256,
176	    ) -> (Address, U256) {
177	        let royalty_info = self.token_royalty_info.get(token_id);
178	        let (royalty_receiver, royalty_fraction) =
179	            if royalty_info.receiver.get().is_zero() {
180	                (
181	                    &self.default_royalty_info.receiver,
182	                    &self.default_royalty_info.royalty_fraction,
183	                )
184	            } else {
185	                (&royalty_info.receiver, &royalty_info.royalty_fraction)
186	            };
187	
188	        let royalty_amount = sale_price
189	            .checked_mul(U256::from(royalty_fraction.get()))
190	            .expect(
191	                "multiplication overflowed in `royalty_amount` calculation.",
192	            )
193	            .checked_div(U256::from(self._fee_denominator()))
194	            .expect("division by zero in `royalty_amount` calculation.");
195	
196	        (royalty_receiver.get(), royalty_amount)
197	    }
198	}
