181	    /// ownership-tracking data structures.
182	    ///
183	    /// # Arguments
184	    ///
185	    /// * `&mut self` - Write access to the contract's state.
186	    /// * `to` - Address representing the new owner of the given `token_id`.
187	    /// * `token_id` - ID of the token to be added to the tokens list of the
188	    ///   given address.
189	    /// * `erc721` - Read access to a contract providing [`IErc721`] interface.
190	    ///
191	    /// # Errors
192	    ///
193	    /// * [`erc721::Error::InvalidOwner`] - If owner address is
194	    ///   [`Address::ZERO`].
195	    pub fn _add_token_to_owner_enumeration(
196	        &mut self,
197	        to: Address,
198	        token_id: U256,
199	        erc721: &impl IErc721<Error = erc721::Error>,
200	    ) -> Result<(), erc721::Error> {
201	        let length = erc721.balance_of(to)? - uint!(1_U256);
202	        self.owned_tokens.setter(to).setter(length).set(token_id);
203	        self.owned_tokens_index.setter(token_id).set(length);
204	
205	        Ok(())
206	    }
