208	    /// Function to add a token to this extension's token
209	    /// tracking data structures.
210	    ///
211	    /// # Arguments
212	    ///
213	    /// * `&mut self` - Write access to the contract's state.
214	    /// * `token_id` - ID of the token to be added to the tokens list.
215	    pub fn _add_token_to_all_tokens_enumeration(&mut self, token_id: U256) {
216	        let index = self.total_supply();
