222	    /// Function to remove a token from this extension's
223	    /// ownership-tracking data structures.
224	    ///
225	    /// Note that while the token is not assigned a new owner,
226	    /// the `self.owned_tokens_index` mapping is NOT updated:
227	    /// this allows for  gas optimizations e.g.
228	    /// when performing a transfer operation (avoiding double writes).
229	    ///
230	    /// This has O(1) time complexity, but alters the order
231	    /// of the `self.owned_tokens` array.
232	    ///
233	    /// # Arguments
234	    ///
235	    /// * `&mut self` - Write access to the contract's state.
236	    /// * `from` - Address representing the previous owner of the given
237	    ///   `token_id`.
238	    /// * `token_id` - ID of the token to be removed from the tokens list of the
239	    ///   given address.
240	    /// * `erc721` - Read access to a contract providing [`IErc721`] interface.
241	    ///
242	    /// # Errors
243	    ///
244	    /// * [`erc721::Error::InvalidOwner`] - If owner address is
245	    ///   [`Address::ZERO`].
246	    pub fn _remove_token_from_owner_enumeration(
247	        &mut self,
248	        from: Address,
249	        token_id: U256,
250	        erc721: &impl IErc721<Error = erc721::Error>,
251	    ) -> Result<(), erc721::Error> {
252	        // To prevent a gap in from's tokens array,
253	        // we store the last token in the index of the token to delete,
254	        // and then delete the last slot (swap and pop).
255	        let last_token_index = erc721.balance_of(from)?;
256	        let token_index = self.owned_tokens_index.get(token_id);
257	
258	        let mut owned_tokens_by_owner = self.owned_tokens.setter(from);
259	
260	        // When the token to delete is the last token,
261	        // the swap operation is unnecessary.
262	        if token_index != last_token_index {
263	            let last_token_id = owned_tokens_by_owner.get(last_token_index);
264	
265	            // Move the last token to the slot of the to-delete token.
266	            owned_tokens_by_owner.setter(token_index).set(last_token_id);
267	            // Update the moved token's index.
268	            self.owned_tokens_index.setter(last_token_id).set(token_index);
269	        }
270	
271	        // This also deletes the contents at the last position of the array.
272	        self.owned_tokens_index.delete(token_id);
273	        owned_tokens_by_owner.delete(last_token_index);
274	
275	        Ok(())
276	    }
