   280	    ///
   281	    /// This has O(1) time complexity,
   282	    /// but alters the order of the `self.all_tokens` array.
   283	    ///
   284	    /// # Arguments
   285	    ///
   286	    /// * `&mut self` - Write access to the contract's state.
   287	    /// * `token_id` -  ID of the token to be removed from the tokens list.
   288	    ///
   289	    /// # Panics
   290	    ///
   291	    /// * The function should not panic in a regular way.
   292	    pub fn _remove_token_from_all_tokens_enumeration(
   293	        &mut self,
   294	        token_id: U256,
   295	    ) {
   296	        // To prevent a gap in the tokens array,
   297	        // we store the last token in the index of the token to delete,
   298	        // and then delete the last slot (swap and pop).
   299	        let last_token_index = U256::from(self.all_tokens.len() - 1);
   300	        let token_index = self.all_tokens_index.get(token_id);
   301	
   302	        // When the token to delete is the last token,
   303	        // the swap operation is unnecessary.
   304	        // However, since this occurs so
   305	        // rarely (when the last minted token is burnt)
   306	        // that we still do the swap here
   307	        // to avoid the gas cost of adding an 'if' statement
   308	        // (like in `self._remove_token_from_owner_enumeration`).
   309	        let last_token_id = self
   310	            .all_tokens
   311	            .get(last_token_index)
   312	            .expect("token at given index must exist");
   313	
   314	        // Move the last token to the slot of the to-delete token.
   315	        self.all_tokens
   316	            .setter(token_index)
   317	            .expect("slot at given `token_index` must exist")
   318	            .set(last_token_id);
   319	
   320	        // Update the moved token's index.
   321	        self.all_tokens_index.setter(last_token_id).set(token_index);
   322	
   323	        // This also deletes the contents at the last position of the array.
   324	        self.all_tokens_index.delete(token_id);
   325	        self.all_tokens.pop();
