   332	    ///
   333	    /// # Arguments
   334	    ///
   335	    /// * `amount` - The number of tokens to increase balance.
   336	    ///
   337	    /// # Errors
   338	    ///
   339	    /// * [`Error::EnumerableForbiddenBatchMint`] - If an `amount` is greater
   340	    ///   than `0`.
   341	    pub fn _check_increase_balance(amount: u128) -> Result<(), Error> {
   342	        if amount > 0 {
   343	            Err(ERC721EnumerableForbiddenBatchMint {}.into())
   344	        } else {
   345	            Ok(())
   346	        }
   347	    }
