295	    /// See [`IErc3156FlashLender::flash_loan`].
296	    #[allow(clippy::missing_panics_doc, clippy::missing_errors_doc)]
297	    pub fn flash_loan(
298	        &mut self,
299	        receiver: Address,
300	        token: Address,
301	        value: U256,
302	        data: &Bytes,
303	        erc20: &mut Erc20,
304	    ) -> Result<bool, Error> {
305	        let max_loan = self.max_flash_loan(token, erc20);
306	        if value > max_loan {
307	            return Err(Error::ExceededMaxLoan(ERC3156ExceededMaxLoan {
308	                max_loan,
309	            }));
310	        }
311	
312	        let fee = self.flash_fee(token, value)?;
313	        if self.vm().code_size(receiver) == 0 {
314	            return Err(Error::ERC3156InvalidReceiver(
315	                ERC3156InvalidReceiver { receiver },
316	            ));
317	        }
318	        erc20._mint(receiver, value)?;
319	        let loan_receiver = IERC3156FlashBorrower::new(receiver);
320	        let vm = self.vm().clone();
321	        let loan_return = loan_receiver
322	            .on_flash_loan(
323	                &vm,
324	                Call::new_mutating(self),
325	                self.vm().msg_sender(),
326	                token,
327	                value,
328	                fee,
329	                data.to_vec().into(),
330	            )
331	            .map_err(|_| {
332	                Error::ERC3156InvalidReceiver(ERC3156InvalidReceiver {
333	                    receiver,
334	                })
335	            })?;
336	        if loan_return != BORROWER_CALLBACK_VALUE {
337	            return Err(Error::ERC3156InvalidReceiver(
338	                ERC3156InvalidReceiver { receiver },
339	            ));
340	        }
341	
342	        let allowance = value
343	            .checked_add(fee)
344	            .expect("allowance should not exceed `U256::MAX`");
345	        erc20._spend_allowance(receiver, self.vm().contract_address(), allowance)?;
346	
347	        let flash_fee_receiver = self.flash_fee_receiver_address.get();
348	
349	        if fee.is_zero() || flash_fee_receiver.is_zero() {
350	            erc20._burn(receiver, allowance)?;
351	        } else {
352	            erc20._burn(receiver, value)?;
353	            erc20._transfer(receiver, flash_fee_receiver, fee)?;
354	        }
355	
356	        Ok(true)
357	    }
358	}
