 12	/// Trait that associate set element with storage type.
 13	pub trait Element: StorageKey + Copy {
 14	    /// Set element type in storage.
 15	    type StorageElement: for<'a> StorageType<Wraps<'a> = Self>
 16	        + Accessor<Wraps = Self>
 17	        + for<'a> SimpleStorageType<'a>
 18	        + Erase;
 19	}
