 21	/// Abstracts accessor inside the contract.
 22	pub trait Accessor {
 23	    /// Type of the number associated with the storage type.
 24	    type Wraps;
 25	
 26	    /// Gets underlying element [`Self::Wraps`] from persistent storage.
 27	    fn get(&self) -> Self::Wraps;
 28	
 29	    /// Sets underlying element [`Self::Wraps`] in persistent storage.
 30	    fn set(&mut self, value: Self::Wraps);
 31	}
 32	
 33	/// Implements [`Element`] and [`Accessor`] traits for a given type.
 34	macro_rules! impl_element_and_accessor {
 35	    ($ty:ty, $storage_ty:ty) => {
 36	        impl Element for $ty {
 37	            type StorageElement = $storage_ty;
 38	        }
 39	
 40	        impl Accessor for $storage_ty {
 41	            type Wraps = $ty;
 42	
 43	            fn get(&self) -> Self::Wraps {
 44	                self.get()
 45	            }
 46	
 47	            fn set(&mut self, value: Self::Wraps) {
 48	                self.set(value);
 49	            }
 50	        }
 51	    };
 52	}
