   397	            let last = next + batch_size - uint!(1_U96);
   398	            self.sequential_ownership.push(last, to.into())?;
   399	
   400	            // The invariant required by this function is preserved because the
   401	            // new sequential_ownership checkpoint is attributing
   402	            // ownership of `batch_size` new tokens to account `to`.
   403	            self.erc721._increase_balance(
   404	                to,
   405	                alloy_primitives::U128::from(batch_size),
   406	            );
