   603	    /// # Events
   604	    ///
   605	    /// * [`Transfer`].
   606	    pub fn _safe_mint(
   607	        &mut self,
   608	        to: Address,
   609	        token_id: U256,
   610	        data: &Bytes,
   611	    ) -> Result<(), Error> {
   612	        self._mint(to, token_id)?;
   613	        Ok(self.erc721._check_on_erc721_received(
   614	            self.vm().msg_sender(),
