   652	    /// Transfers `token_id` from `from` to `to`.
   653	    ///
   654	    /// As opposed to [`Self::transfer_from`], this imposes no restrictions on
   655	    /// `msg::sender`.
   656	    ///
   657	    /// # Arguments
   658	    ///
   659	    /// * `&mut self` - Write access to the contract's state.
   660	    /// * `from` - Account of the sender.
   661	    /// * `to` - Account of the recipient.
   662	    /// * `token_id` - Token id as a number.
   663	    ///
   664	    /// # Errors
   665	    ///
   666	    /// * [`erc721::Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
   667	    /// * [`erc721::Error::NonexistentToken`] - If `token_id` does not exist.
   668	    /// * [`erc721::Error::IncorrectOwner`] - If the previous owner is not
   669	    ///   `from`.
   670	    ///
   671	    /// # Events
   672	    ///
   673	    /// * [`Transfer`].
   674	    pub fn _transfer(
   675	        &mut self,
   676	        from: Address,
   677	        to: Address,
   678	        token_id: U256,
   679	    ) -> Result<(), Error> {
   680	        if to.is_zero() {
   681	            return Err(erc721::Error::InvalidReceiver(
   682	                ERC721InvalidReceiver { receiver: Address::ZERO },
   683	            )
   684	            .into());
   685	        }
   686	
   687	        let previous_owner = self._update(to, token_id, Address::ZERO)?;
   688	        if previous_owner.is_zero() {
   689	            return Err(erc721::Error::NonexistentToken(
   690	                ERC721NonexistentToken { token_id },
   691	            )
   692	            .into());
   693	        } else if previous_owner != from {
   694	            return Err(erc721::Error::IncorrectOwner(ERC721IncorrectOwner {
   695	                sender: from,
   696	                token_id,
   697	                owner: previous_owner,
   698	            })
   699	            .into());
   700	        }
   701	
   702	        Ok(())
   703	    }
