   772	    ///   to approve this token.
   773	    ///
   774	    /// # Events
   775	    ///
   776	    /// * [`Approval`].
   777	    pub fn _approve(
   778	        &mut self,
   779	        to: Address,
   780	        token_id: U256,
   781	        auth: Address,
   782	        emit_event: bool,
   783	    ) -> Result<(), Error> {
