 574	impl SafeErc20 {
 575	    /// Imitates a Stylus high-level call, relaxing the requirement on the
 576	    /// return value: if data is returned, it must not be `false`, otherwise
 577	    /// calls are assumed to be successful.
 578	    ///
 579	    /// # Arguments
 580	    ///
 581	    /// * `token` - Address of the ERC-20 token contract.
 582	    /// * `call` - [`IErc20`] call that implements [`SolCall`] trait.
 583	    ///
 584	    /// # Errors
 585	    ///
 586	    /// * [`Error::SafeErc20FailedOperation`] - If the `token` address is not a
 587	    ///    the contract fails to execute the call or the call returns
 588	    ///   value that is not `true`.
 589	    fn call_optional_return(
 590	        &mut self,
 591	        token: Address,
 592	        call: &impl SolCall,
 593	    ) -> Result<(), Error> {
 594	        if self.vm().code_size(token) == 0 {
 595	            return Err(Error::SafeErc20FailedOperation(
 596	                SafeErc20FailedOperation { token },
 597	            ));
 598	        }
 599	
 600	        let result = unsafe {
 601	            RawCall::new(self.vm())
 602	                .limit_return_data(0, BOOL_TYPE_SIZE)
 603	                .flush_storage_cache()
 604	                .call(token, &call.abi_encode())
 605	        };
 606	
 607	        match result {
 608	            Ok(data)
 609	                if data.is_empty()
 610	                    || Bool::abi_decode(&data)
 611	                        .is_ok_and(|success| success) =>
 612	            {
 613	                Ok(())
 614	            }
 615	            _ => Err(SafeErc20FailedOperation { token }.into()),
 616	        }
 617	    }
 618	
 619	    /// Returns the remaining number of ERC-20 tokens that `spender`
 620	    /// will be allowed to spend on behalf of an owner.
 621	    ///
 622	    /// # Arguments
 623	    ///
 624	    /// * `&self` - Read access to the contract's state.
 625	    /// * `token` - Address of the ERC-20 token contract.
 626	    /// * `spender` - Account that will spend the tokens.
 627	    ///
 628	    /// # Errors
 629	    ///
 630	    /// * [`Error::SafeErc20FailedOperation`] - If the contract fails to read
 631	    ///   `spender`'s allowance.
 632	    fn allowance(
 633	        &self,
 634	        token: Address,
 635	        spender: Address,
 636	    ) -> Result<U256, Error> {
 637	        if self.vm().code_size(token) == 0 {
 638	            return Err(SafeErc20FailedOperation { token }.into());
 639	        }
 640	
 641	        let erc20 = Erc20Interface::new(token);
 642	        erc20.allowance(self.vm(), Call::new(), self.vm().contract_address(), spender).map_err(|_e| {
 643	            Error::SafeErc20FailedOperation(SafeErc20FailedOperation { token })
 644	        })
 645	    }
 646	}
