324	    /// * `token_id` - Token id as a number.
325	    pub fn _owner_of(&self, token_id: U256) -> Address {
326	        let owner = self.erc721._owner_of(token_id);
327	        // If token is owned by the core, or beyond consecutive range, return
328	        // base value.
329	        if !owner.is_zero()
330	            || token_id < U256::from(self._first_consecutive_id())
331	            || token_id > U256::from(U96::MAX)
332	        {
333	            return owner;
334	        }
335	
336	        // Otherwise, check the token was not burned, and fetch ownership from
337	        // the anchors.
338	        if self.sequential_burn.get(token_id) {
339	            Address::ZERO
340	        } else {
341	            // NOTE: Bounds already checked. No need for safe cast of token_id
342	            self.sequential_ownership.lower_lookup(U96::from(token_id)).into()
343	        }
