348	    /// `batch_size` is 0, returns the number of consecutive ids minted so
349	    /// far.
350	    ///
351	    /// CAUTION: Does not emit a [`Transfer`] event. This is ERC-721 compliant
352	    /// as long as it is done inside of the constructor, which is enforced by
353	    /// this function.
354	    ///
355	    /// CAUTION: Does not invoke
356	    /// [`erc721::IErc721Receiver::on_erc721_received`] on the receiver.
357	    ///
358	    /// # Arguments
359	    ///
360	    /// * `&self` - Write access to the contract's state.
361	    /// * `token_id` - Token id as a number.
362	    ///
363	    /// # Errors
364	    ///
365	    /// * [`erc721::Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
366	    /// * [`Error::ExceededMaxBatchMint`] - If `batch_size` exceeds
367	    ///   `max_batch_size` of the contract.
368	    ///
369	    /// # Events
370	    ///
371	    /// * [`ConsecutiveTransfer`].
372	    pub fn _mint_consecutive(
373	        &mut self,
374	        to: Address,
375	        batch_size: U96,
376	    ) -> Result<U96, Error> {
377	        let next = self._next_consecutive_id();
378	
379	        // Minting a batch of size 0 is a no-op.
380	        if batch_size > U96::ZERO {
