659	        to: Address,
660	        token_id: U256,
661	        auth: Address,
662	    ) -> Result<Address, Error> {
663	        let from = self._owner_of(token_id);
664	
665	        // Perform (optional) operator check.
666	        if !auth.is_zero() {
667	            self._check_authorized(from, auth, token_id)?;
668	        }
669	
670	        // Execute the update.
671	        if !from.is_zero() {
672	            // Clear approval. No need to re-authorize or emit the `Approval`
673	            // event.
674	            self._approve(Address::ZERO, token_id, Address::ZERO, false)?;
675	            self.balances.setter(from).sub_assign_unchecked(uint!(1_U256));
676	        }
677	
678	        if !to.is_zero() {
679	            self.balances.setter(to).add_assign_unchecked(uint!(1_U256));
680	        }
681	
682	        self.owners.setter(token_id).set(to);
683	        self.vm().log(Transfer { from, to, token_id });
684	        Ok(from)
685	    }
686	
687	    /// Mints `token_id` and transfers it to `to`.
688	    ///
689	    /// WARNING: Usage of this method is discouraged, use [`Self::_safe_mint`]
690	    /// whenever possible.
691	    ///
692	    /// # Arguments
693	    ///
694	    /// * `&mut self` - Write access to the contract's state.
695	    /// * `to` - Account of the recipient.
696	    /// * `token_id` - Token id as a number.
697	    ///
698	    /// # Errors
699	    ///
700	    /// * [`Error::InvalidSender`] - If `token_id` already exists.
701	    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
702	    ///
703	    /// # Events
704	    ///
705	    /// * [`Transfer`].
706	    pub fn _mint(&mut self, to: Address, token_id: U256) -> Result<(), Error> {
707	        if to.is_zero() {
708	            return Err(
709	                ERC721InvalidReceiver { receiver: Address::ZERO }.into()
710	            );
711	        }
712	
713	        let previous_owner = self._update(to, token_id, Address::ZERO)?;
714	        if !previous_owner.is_zero() {
715	            return Err(ERC721InvalidSender { sender: Address::ZERO }.into());
716	        }
717	        Ok(())
718	    }
719	
720	    /// Mints `token_id`, transfers it to `to`,
721	    /// and checks for `to`'s acceptance.
722	    ///
723	    /// An additional `data` parameter is forwarded to
724	    /// [`IErc721Receiver::on_erc721_received`] to contract recipients.
725	    ///
726	    /// # Arguments
727	    ///
728	    /// * `&mut self` - Write access to the contract's state.
729	    /// * `to` - Account of the recipient.
730	    /// * `token_id` - Token id as a number.
731	    /// * `data` - Additional data with no specified format, sent in the call to
732	    ///   [`Erc721::_check_on_erc721_received`].
733	    ///
734	    /// # Errors
735	    ///
440	    /// # Events
441	    ///
442	    /// * [`TransferSingle`] - If the arrays contain one element.
443	    /// * [`TransferBatch`] - If the arrays contain multiple elements.
444	    ///
445	    /// # Panics
446	    ///
447	    /// * If updated balance exceeds [`U256::MAX`], may happen during `mint`
448	    ///   operation.
449	    fn _update(
450	        &mut self,
451	        from: Address,
452	        to: Address,
453	        ids: Vec<U256>,
454	        values: Vec<U256>,
455	    ) -> Result<(), Error> {
456	        Self::require_equal_arrays_length(&ids, &values)?;
457	
458	        let operator = self.vm().msg_sender();
459	
460	        for (&token_id, &value) in ids.iter().zip(values.iter()) {
461	            self.do_update(from, to, token_id, value)?;
462	        }
463	
464	        if ids.len() == 1 {
465	            let id = ids[0];
466	            let value = values[0];
467	            self.vm().log(TransferSingle { operator, from, to, id, value });
468	        } else {
469	            self.vm().log(TransferBatch { operator, from, to, ids, values });
470	        }
471	
472	        Ok(())
473	    }
474	
475	    /// Version of [`Self::_update`] that performs the token acceptance check by
476	    /// calling [`IErc1155Receiver::on_erc1155_received`] or
477	    /// [`IErc1155Receiver::on_erc1155_batch_received`] on the receiver address
478	    /// if it contains code.
479	    ///
480	    /// # Arguments
481	    ///
482	    /// * `&mut self` - Write access to the contract's state.
483	    /// * `from` - Account to transfer tokens from.
484	    /// * `to` - Account of the recipient.
485	    /// * `ids` - Array of all token ids.
486	    /// * `values` - Array of all amount of tokens to be transferred.
487	    /// * `data` - Additional data with no specified format, sent in call to
488	    ///   `to`.
489	    ///
490	    /// # Errors
491	    ///
492	    /// * [`Error::InvalidArrayLength`] - Returned when length of `ids` is not
493	    ///   equal to length of `values`.
494	    /// * [`Error::InsufficientBalance`] - Returned when `value` is greater than
495	    ///   the balance of the `from` account.
496	    /// * [`Error::InvalidReceiver`] - Returned when
497	    ///   [`IErc1155Receiver::on_erc1155_received`] or
498	    ///   [`IErc1155Receiver::on_erc1155_batch_received`] hasn't returned its
499	    ///   interface id or returned with error.
500	    ///
501	    /// # Events
502	    ///
503	    /// * [`TransferSingle`] - If the arrays contain one element.
504	    /// * [`TransferBatch`] - If the arrays contain multiple elements.
505	    ///
506	    /// # Panics
507	    ///
508	    /// * If updated balance exceeds [`U256::MAX`], may happen during `mint`
509	    ///   operation.
510	    fn _update_with_acceptance_check(
511	        &mut self,
512	        from: Address,
513	        to: Address,
514	        ids: Vec<U256>,
515	        values: Vec<U256>,
516	        data: &Bytes,
517	    ) -> Result<(), Error> {
518	        self._update(from, to, ids.clone(), values.clone())?;
519	
520	        if !to.is_zero() {
521	            self._check_on_erc1155_received(
522	                self.vm().msg_sender(),
523	                from,
524	                to,
525	                Erc1155ReceiverData::new(ids, values),
526	                data.to_vec().into(),
527	            )?;
528	        }
529	
530	        Ok(())
531	    }
