535	    ///
300	
301	    fn allowance(&self, owner: Address, spender: Address) -> U256 {
302	        self.allowances.get(owner).get(spender)
303	    }
304	
305	    fn approve(
306	        &mut self,
307	        spender: Address,
308	        value: U256,
309	    ) -> Result<bool, Self::Error> {
310	        let owner = self.vm().msg_sender();
311	        self._approve(owner, spender, value, true)
312	    }
313	
314	    fn transfer_from(
315	        &mut self,
316	        from: Address,
317	        to: Address,
318	        value: U256,
319	    ) -> Result<bool, Self::Error> {
320	        let spender = self.vm().msg_sender();
321	        self._spend_allowance(from, spender, value)?;
322	        self._transfer(from, to, value)?;
323	        Ok(true)
324	    }
325	}
