        account: Address,
        value: U256,
        erc20: &mut Erc20,
    ) -> Result<bool, Error> {
        let contract_address = self.vm().contract_address();
        let sender = self.vm().msg_sender();

        if sender == contract_address {
            return Err(erc20::ERC20InvalidSender { sender }.into());
