//! Optional Burnable extension of the ERC-20 standard.

use alloy_primitives::{Address, U256};
use stylus_sdk::prelude::{HostAccess, MessageAccess};

use crate::token::erc20::{self, Erc20};

/// Extension of [`Erc20`] that allows token holders to destroy both
/// their own tokens and those that they have an allowance for,
/// in a way that can be recognized off-chain (via event analysis).
#[allow(missing_docs)]
#[stylus_sdk::prelude::public]
pub trait IErc20Burnable {
    /// The error type associated to this ERC-20 Burnable trait implementation.
    type Error: Into<alloc::vec::Vec<u8>>;

    /// Destroys a `value` amount of tokens from the caller, lowering the total
    /// supply.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `value` - Amount to be burnt.
    ///
    /// # Errors
    ///
    /// * [`erc20::Error::InsufficientBalance`] - If the `from` address doesn't
    ///   have enough tokens.
    ///
    /// # Events
    ///
    /// * [`erc20::Transfer`].
    fn burn(&mut self, value: U256) -> Result<(), Self::Error>;

    /// Destroys a `value` amount of tokens from `account`, lowering the total
    /// supply.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `account` - Owner's address.
    /// * `value` - Amount to be burnt.
    ///
    /// # Errors
    ///
    /// * [`erc20::Error::InsufficientAllowance`] - If not enough allowance is
    ///   available.
    /// * [`erc20::Error::InvalidSender`] - If the `from` address is
    ///   [`Address::ZERO`].
    /// * [`erc20::Error::InsufficientBalance`] - If the `from` address doesn't
    ///   have enough tokens.
    ///
    /// # Events
    ///
    /// * [`erc20::Transfer`].
    fn burn_from(
        &mut self,
        account: Address,
        value: U256,
    ) -> Result<(), Self::Error>;
}

impl IErc20Burnable for Erc20 {
    #[cfg(not(feature = "contract-client-gen"))]
    fn __stylus_trait_and_impl_must_be_tagged_with_public_macro(&self) {}

    type Error = erc20::Error;

    fn burn(&mut self, value: U256) -> Result<(), erc20::Error> {
        self._burn(self.vm().msg_sender(), value)
    }

    fn burn_from(
        &mut self,
        account: Address,
        value: U256,
    ) -> Result<(), erc20::Error> {
        self._spend_allowance(account, self.vm().msg_sender(), value)?;
        self._burn(account, value)
    }
}

#[cfg(test)]
mod tests {
    use crate::test_support::{test_address, TestContract as TestVMContract};
    use alloy_primitives::{uint, Address, U256};

    use super::IErc20Burnable;
    use crate::token::erc20::{Erc20, Error, IErc20};

    #[test]
    fn burns() {
        let contract = TestVMContract::<Erc20>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let zero = U256::ZERO;
        let one = uint!(1_U256);

        assert_eq!(zero, contract.sender(alice).total_supply());

        // Mint some tokens for Alice.

        let two = uint!(2_U256);
        contract.sender(alice)._update(Address::ZERO, alice, two).unwrap();
        assert_eq!(two, contract.sender(alice).balance_of(alice));
        assert_eq!(two, contract.sender(alice).total_supply());

        contract.sender(alice).burn(one).unwrap();

        assert_eq!(one, contract.sender(alice).balance_of(alice));
        assert_eq!(one, contract.sender(alice).total_supply());
    }

    #[test]
    fn burns_errors_when_insufficient_balance() {
        let contract = TestVMContract::<Erc20>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let zero = U256::ZERO;
        let one = uint!(1_U256);

        assert_eq!(zero, contract.sender(alice).balance_of(alice));

        let result = contract.sender(alice).burn(one);
        assert!(matches!(result, Err(Error::InsufficientBalance(_))));

        erc20._mint(receiver, shares)?;

        self.vm().log(Deposit {
            sender: caller,
            owner: receiver,
            assets,
            shares,
        });

        Ok(())
    }

    /// Withdraw/redeem common workflow.
    ///
    /// # Arguments
    ///
    /// * `caller` - Address initiating the withdrawal.
    /// * `receiver` - Address receiving the assets.
    /// * `owner` - Address owning the shares.
    /// * `assets` - Amount of underlying tokens to transfer.
    /// * `shares` - Amount of shares to burn.
    /// * `erc20` - Write access to an [`Erc20`] contract.
    ///
    /// # Errors
    ///
    /// * [`erc20::Error::InsufficientAllowance`] - If `caller` needs allowance.
    /// * [`erc20::Error::InvalidApprover`] - If `owner` is [`Address::ZERO`].
    /// * [`erc20::Error::InsufficientBalance`] - If `owner` lacks shares.
    /// * [`safe_erc20::Error::SafeErc20FailedOperation`] - If transfer fails.
    ///
    /// # Events
    ///
    /// * [`Withdraw`]
    pub fn _withdraw(
        &mut self,
        caller: Address,
        receiver: Address,
        owner: Address,
        assets: U256,
        shares: U256,
        erc20: &mut Erc20,
    ) -> Result<(), Error> {
        if caller != owner {
            erc20._spend_allowance(owner, caller, shares)?;
        }

        // If asset() is ERC-777, `transfer` can trigger a reentrancy AFTER the
        // transfer happens through the `tokens_received` hook. On the other
        // hand, the `tokens_to_send` hook, that is triggered before the
        // transfer, calls the vault, which is assumed not malicious.
        //
        // Conclusion: we need to do the transfer after the burn so that any
        // reentrancy would happen after the shares are burned and after the
        // assets are transferred, which is a valid state.

        erc20._burn(owner, shares)?;

        self.safe_erc20.safe_transfer(self.asset(), receiver, assets)?;

        self.vm().log(Withdraw {
            sender: caller,
            receiver,
            owner,
            assets,
            shares,
        });

        Ok(())
    }

    /// Returns the decimals offset between the underlying asset and vault
    /// shares.
    /// Currently, always returns [`U8::ZERO`].
    #[must_use]
    pub fn _decimals_offset(&self) -> U8 {
        self.decimals_offset.get()
    }
}

impl Erc4626 {
        receiver: Address,
        token: Address,
        value: U256,
        data: &Bytes,
        erc20: &mut Erc20,
    ) -> Result<bool, Error> {
        let max_loan = self.max_flash_loan(token, erc20);
        if value > max_loan {
            return Err(Error::ExceededMaxLoan(ERC3156ExceededMaxLoan {
                max_loan,
            }));
        }

        let fee = self.flash_fee(token, value)?;
        if self.vm().code_size(receiver) == 0 {
            return Err(Error::ERC3156InvalidReceiver(
                ERC3156InvalidReceiver { receiver },
            ));
        }
        erc20._mint(receiver, value)?;
        let loan_receiver = IERC3156FlashBorrower::new(receiver);
        let vm = self.vm().clone();
        let loan_return = loan_receiver
            .on_flash_loan(
                &vm,
                Call::new_mutating(self),
                self.vm().msg_sender(),
                token,
                value,
                fee,
                data.to_vec().into(),
            )
            .map_err(|_| {
                Error::ERC3156InvalidReceiver(ERC3156InvalidReceiver {
                    receiver,
                })
            })?;
        if loan_return != BORROWER_CALLBACK_VALUE {
            return Err(Error::ERC3156InvalidReceiver(
                ERC3156InvalidReceiver { receiver },
            ));
        }

        let allowance = value
            .checked_add(fee)
            .expect("allowance should not exceed `U256::MAX`");
        erc20._spend_allowance(
            receiver,
            self.vm().contract_address(),
            allowance,
        )?;

        let flash_fee_receiver = self.flash_fee_receiver_address.get();

        if fee.is_zero() || flash_fee_receiver.is_zero() {
            erc20._burn(receiver, allowance)?;
        } else {
            erc20._burn(receiver, value)?;
            erc20._transfer(receiver, flash_fee_receiver, fee)?;
        }

        Ok(true)
    }
}

