121	/// Contains arguments of the `#[selector(..)]` attribute.
122	struct SelectorArgs {
123	    name: String,
124	}
125	
126	impl Parse for SelectorArgs {
127	    fn parse(input: ParseStream) -> Result<Self> {
128	        let ident: Ident = input.parse()?;
129	
130	        if ident == "name" {
131	            let _: Token![=] = input.parse()?;
132	            let lit: LitStr = input.parse()?;
133	            Ok(SelectorArgs { name: lit.value() })
134	        } else {
135	            error!(@ident, "expected identifier 'name'")
136	        }
137	    }
138	}
