  1	//! Defines the `#[interface_id]` procedural macro.
  2	
  3	use std::{collections::HashMap, mem};
  4	
  5	use convert_case::{Case, Casing};
  6	use proc_macro::TokenStream;
  7	use proc_macro2::Ident;
  8	use quote::quote;
  9	use syn::{
 10	    parse::{Parse, ParseStream},
 11	    parse_macro_input, FnArg, ItemTrait, LitStr, Result, Token, TraitItem,
 12	};
 13	
 14	/// Computes an interface id as an associated function for the trait.
 15	pub(crate) fn interface_id(
 16	    _attr: &TokenStream,
 17	    input: TokenStream,
 18	) -> TokenStream {
 19	    let mut input = parse_macro_input!(input as ItemTrait);
 20	
 21	    let unsafety = input.unsafety;
 22	    let mut selectors_map =
 23	        HashMap::<String, (String, proc_macro2::TokenStream)>::new();
 24	
 25	    for item in &mut input.items {
 26	        let TraitItem::Fn(func) = item else {
 27	            continue;
 28	        };
 29	
 30	        let mut override_fn_name = None;
 31	        for attr in mem::take(&mut func.attrs) {
 32	            if attr.path().is_ident("selector") {
 33	                if override_fn_name.is_some() {
 34	                    error!(attr.path(), "more than one selector attribute");
 35	                }
 36	                let args: SelectorArgs = match attr.parse_args() {
 37	                    Ok(args) => args,
 38	                    Err(error) => error!(attr.path(), "{}", error),
 39	                };
 40	                override_fn_name = Some(args.name);
 41	            } else {
 42	                // Put back any other attributes.
 43	                func.attrs.push(attr);
 44	            }
 45	        }
 46	
 47	        let rust_fn_name = func.sig.ident.to_string();
 48	
 49	        let solidity_fn_name =
 50	            override_fn_name.unwrap_or(rust_fn_name.to_case(Case::Camel));
 51	
 52	        let arg_types = func.sig.inputs.iter().filter_map(|arg| match arg {
 53	            FnArg::Typed(t) => Some(t.ty.clone()),
 54	            // Opt out any `self` arguments.
 55	            FnArg::Receiver(_) => None,
 56	        });
 57	
 58	        // Build the function signature string for selector computation.
 59	        let type_strings: Vec<String> =
 60	            arg_types.clone().map(|ty| quote!(#ty).to_string()).collect();
 61	        let signature =
 62	            format!("{}({})", solidity_fn_name, type_strings.join(","));
 63	
 64	        let selector = quote! { alloy_primitives::aliases::B32::new(stylus_sdk::function_selector!(#solidity_fn_name #(, #arg_types )*)) };
 65	
 66	        // Store selector expression from every function in the trait.
 67	        match selectors_map.get(&signature) {
 68	            Some((existing_rust_fn_name, _)) => {
 69	                error!(
 70	                    existing_rust_fn_name,
 71	                    "selector collision detected: function '{}' has the same selector as function '{}': {}",
 72	                    rust_fn_name,
 73	                    existing_rust_fn_name,
 74	                    signature,
 75	                );
 76	            }
 77	            None => selectors_map.insert(signature, (rust_fn_name, selector)),
 78	        };
 79	    }
 80	
 81	    let name = input.ident;
 82	    let vis = input.vis;
 83	    let attrs = input.attrs;
 84	    let trait_items = input.items;
 85	    let generics = input.generics.clone();
 86	    let where_clause = &generics.where_clause;
 87	
 88	    let supertrait_tokens = if input.supertraits.is_empty() {
 89	        quote! {}
 90	    } else {
 91	        let supertraits = &input.supertraits;
 92	        quote! { : #supertraits }
 93	    };
 94	
 95	    let selectors = selectors_map.values().map(|(_, tokens)| tokens);
 96	
 97	    // Keep the same trait with an additional associated function
 98	    // `interface_id`.
 99	    quote! {
100	        #(#attrs)*
101	        #vis #unsafety trait #name #generics #supertrait_tokens #where_clause {
102	            #(#trait_items)*
103	
104	            #[cfg(not(feature = "contract-client-gen"))]
105	            #[allow(missing_docs)]
106	            fn __stylus_trait_and_impl_must_be_tagged_with_public_macro(&self);
107	
108	            #[doc = concat!("Solidity interface id associated with ", stringify!(#name), " trait.")]
109	            #[doc = "Computed as a XOR of selectors for each function in the trait."]
110	            fn interface_id() -> alloy_primitives::aliases::B32
111	            where
112	                Self: Sized,
113	            {
114	                #(#selectors)^*
115	            }
116	        }
117	    }
118	    .into()
119	}
120	
121	/// Contains arguments of the `#[selector(..)]` attribute.
122	struct SelectorArgs {
123	    name: String,
124	}
125	
126	impl Parse for SelectorArgs {
127	    fn parse(input: ParseStream) -> Result<Self> {
128	        let ident: Ident = input.parse()?;
129	
130	        if ident == "name" {
131	            let _: Token![=] = input.parse()?;
132	            let lit: LitStr = input.parse()?;
133	            Ok(SelectorArgs { name: lit.value() })
134	        } else {
135	            error!(@ident, "expected identifier 'name'")
136	        }
137	    }
138	}
  1	//! This module contains low-level arithmetic functions for
  2	//! big integer's limbs.
  3	
  4	// Actually cast truncations are a part of the logic here.
  5	#![allow(clippy::cast_possible_truncation, clippy::cast_lossless)]
  6	
  7	use num_traits::ConstOne;
  8	
  9	/// A single limb of a big integer represented by 64-bits.
 10	pub type Limb = u64;
 11	
 12	/// Array of [`Limb`]s.
 13	pub type Limbs<const N: usize> = [Limb; N];
 14	
 15	/// A wide limb represented by 128-bits.
 16	///
 17	/// Twice larger than [`Limb`].
 18	pub type WideLimb = u128;
 19	
 20	/// Multiply two [`Limb`]'s and return widened result.
 21	#[inline(always)]
 22	#[must_use]
 23	pub const fn widening_mul(a: Limb, b: Limb) -> WideLimb {
 24	    #[cfg(not(target_family = "wasm"))]
 25	    {
 26	        a as WideLimb * b as WideLimb
 27	    }
 28	    #[cfg(target_family = "wasm")]
 29	    {
 30	        widening_mul_wasm(a, b)
 31	    }
 32	}
 33	
 34	/// Multiply two [`Limb`]'s and return widened result.
 35	///
 36	/// This function is optimized for wasm target, due to inefficiency of
 37	/// 128-bit multiplication in WebAssembly.
 38	#[inline(always)]
 39	#[doc(hidden)]
 40	#[allow(dead_code)]
 41	const fn widening_mul_wasm(a: Limb, b: Limb) -> WideLimb {
 42	    let a_lo = a as u32 as Limb;
 43	    let a_hi = a >> 32;
 44	    let b_lo = b as u32 as Limb;
 45	    let b_hi = b >> 32;
 46	
 47	    let lolo = (a_lo * b_lo) as WideLimb;
 48	    let lohi = ((a_lo * b_hi) as WideLimb) << 32;
 49	    let hilo = ((a_hi * b_lo) as WideLimb) << 32;
 50	    let hihi = ((a_hi * b_hi) as WideLimb) << 64;
 51	    (lolo | hihi) + (lohi + hilo)
 52	}
 53	
 54	/// Calculate `a + b * c`, returning the lower 64 bits of the result and setting
 55	/// `carry` to the upper 64 bits.
 56	#[inline(always)]
 57	#[must_use]
 58	pub const fn mac(a: Limb, b: Limb, c: Limb) -> (Limb, Limb) {
 59	    let a = a as WideLimb;
 60	    let tmp = a + widening_mul(b, c);
 61	    let carry = (tmp >> Limb::BITS) as Limb;
 62	    (tmp as Limb, carry)
 63	}
 64	
 65	/// Calculate `a + (b * c) + carry`, returning the least significant digit
 66	/// and setting carry to the most significant digit.
 67	#[inline(always)]
 68	#[must_use]
 69	pub const fn carrying_mac(
 70	    a: Limb,
 71	    b: Limb,
 72	    c: Limb,
 73	    carry: Limb,
 74	) -> (Limb, Limb) {
 75	    let a = a as WideLimb;
 76	    let carry = carry as WideLimb;
 77	    let tmp = a + widening_mul(b, c) + carry;
 78	    let carry = (tmp >> Limb::BITS) as Limb;
 79	    (tmp as Limb, carry)
 80	}
 81	
 82	/// Calculate `a = a + b + carry` and return the result and carry.
 83	#[inline(always)]
 84	#[must_use]
 85	pub const fn adc(a: Limb, b: Limb, carry: bool) -> (Limb, bool) {
 86	    let a = a as WideLimb;
 87	    let b = b as WideLimb;
 88	    let carry = carry as WideLimb;
 89	    let tmp = a + b + carry;
 90	    let carry = (tmp >> Limb::BITS) != 0;
 91	    (tmp as Limb, carry)
 92	}
 93	
 94	/// Sets a = a + b + carry, and returns the new carry.
 95	#[inline(always)]
 96	pub fn adc_assign(a: &mut Limb, b: Limb, carry: bool) -> bool {
 97	    let tmp = *a as WideLimb + b as WideLimb + carry as WideLimb;
 98	    *a = tmp as Limb;
 99	    let carry = tmp >> Limb::BITS;
100	    carry != 0
101	}
102	
103	/// Calculate `a = a - b - borrow` and return the result and borrow.
104	#[inline(always)]
105	#[must_use]
106	pub const fn sbb(a: Limb, b: Limb, borrow: bool) -> (Limb, bool) {
107	    let a = a as WideLimb;
108	    let b = b as WideLimb;
109	    let borrow = borrow as WideLimb;
110	    // Protects from overflow, when `a < b + borrow`.
111	    let overflow_protection = WideLimb::ONE << Limb::BITS;
112	    let tmp = overflow_protection + a - b - borrow;
113	    let borrow = tmp >> Limb::BITS == 0;
114	    // overflow_protection will be truncated on cast.
115	    (tmp as Limb, borrow)
116	}
117	
118	/// Sets a = a - b - borrow, and returns the borrow.
119	#[inline(always)]
120	pub fn sbb_assign(a: &mut Limb, b: Limb, borrow: bool) -> bool {
121	    let (sub, borrow1) = a.overflowing_sub(b);
122	    let (sub, borrow2) = sub.overflowing_sub(borrow as Limb);
123	    *a = sub;
124	    borrow1 | borrow2
125	}
