 66	impl Erc721Metadata {
 67	    /// Constructor.
 68	    ///
 69	    /// # Arguments
 70	    ///
 71	    /// * `&mut self` - Write access to the contract's state.
 72	    /// * `name` - Token name.
 73	    /// * `symbol` - Token symbol.
 74	    pub fn constructor(&mut self, name: String, symbol: String) {
 75	        self.metadata.constructor(name, symbol);
 76	    }
