 79	    pub fn name(&self) -> String {
 80	        self.metadata.name()
 81	    }
 82	
 83	    /// Check [`IErc721Metadata::symbol()`] for more details.
 84	    pub fn symbol(&self) -> String {
 85	        self.metadata.symbol()
 86	    }
 87	
 88	    /// Returns the base of Uniform Resource Identifier (URI) for tokens'
 89	    /// collection.
 90	    ///
 91	    /// # Arguments
 92	    ///
 93	    /// * `&self` - Read access to the contract's state.
 94	    pub fn base_uri(&self) -> String {
 95	        self.base_uri.get_string()
 96	    }
 97	
 98	    /// Check [`IErc721Metadata::token_uri()`] for more details.
 99	    #[allow(clippy::missing_errors_doc)]
100	    pub fn token_uri(
101	        &self,
102	        token_id: U256,
103	        erc721: &impl IErc721<Error = erc721::Error>,
104	    ) -> Result<String, erc721::Error> {
105	        erc721.owner_of(token_id)?;
106	
107	        let base_uri = self.base_uri();
108	
109	        let token_uri = if base_uri.is_empty() {
110	            String::new()
111	        } else {
112	            base_uri + &token_id.to_string()
113	        };
114	
115	        Ok(token_uri)
116	    }
117	}
