366	    /// Writes a previously validated allowance remainder after the associated
367	    /// token operation succeeds.
368	    pub(crate) fn _write_spent_allowance(
369	        &mut self,
370	        owner: Address,
371	        spender: Address,
372	        remaining_allowance: Option<U256>,
373	    ) -> Result<(), Error> {
374	        if let Some(allowance) = remaining_allowance {
375	            self._approve(owner, spender, allowance, false)?;
376	        }
377	        Ok(())
378	    }
