380	    /// Sets a `value` number of tokens as the allowance of `spender` over the
381	    /// caller's tokens.
382	    ///
383	    /// Returns a boolean value indicating whether the operation succeeded.
384	    /// # Arguments
385	    ///
386	    /// * `&mut self` - Write access to the contract's state.
387	    /// * `owner` - Account that owns the tokens.
388	    /// * `spender` - Account that will spend the tokens.
389	    /// * `emit_event` - Emit an [`Approval`] event flag.
390	    ///
391	    /// # Errors
392	    ///
393	    /// * [`Error::InvalidSpender`] - If the `spender` address is
394	    ///   [`Address::ZERO`].
395	    ///
396	    /// # Events
397	    ///
398	    /// * [`Approval`].
399	    fn _approve(
400	        &mut self,
401	        owner: Address,
402	        spender: Address,
403	        value: U256,
404	        emit_event: bool,
405	    ) -> Result<bool, Error> {
406	        if owner.is_zero() {
407	            return Err(Error::InvalidApprover(ERC20InvalidApprover {
408	                approver: Address::ZERO,
409	            }));
410	        }
411	
412	        if spender.is_zero() {
413	            return Err(Error::InvalidSpender(ERC20InvalidSpender {
414	                spender: Address::ZERO,
415	            }));
416	        }
417	
418	        self.allowances.setter(owner).insert(spender, value);
419	        if emit_event {
420	            self.vm().log(Approval { owner, spender, value });
421	        }
422	        Ok(true)
423	    }
