 154	    /// Checks `self` is less then `rhs` (constant).
 155	    #[must_use]
 156	    #[inline(always)]
 157	    pub const fn lt(&self, rhs: &Self) -> bool {
 158	        let mut result = false;
 159	        const_for_unroll6!((i in 0..N) {
 160	            let a = self.limbs[i];
 161	            let b = rhs.limbs[i];
 162	            if a < b {
 163	                result = true;
 164	            } else if a > b {
 165	                result = false;
 166	            }
 167	        });
 168	        result
 169	    }
