1042	const fn parse_digit(utf8_digit: u8, digit_radix: u32) -> u32 {
1043	    let ch = parse_utf8_byte(utf8_digit);
1044	    match ch.to_digit(digit_radix) {
1045	        None => {
1046	            panic!("invalid digit");
1047	        }
1048	        Some(digit) => digit,
1049	    }
1050	}
