 236	        &mut self,
 237	        account: Address,
 238	        value: U256,
 239	        erc20: &mut Erc20,
 240	    ) -> Result<bool, Error> {
 241	        let contract_address = self.vm().contract_address();
 242	        let sender = self.vm().msg_sender();
 243	
 244	        if sender == contract_address {
 245	            return Err(erc20::ERC20InvalidSender { sender }.into());
 246	        }
 247	
 248	        if account == contract_address {
 249	            return Err(
 250	                erc20::ERC20InvalidReceiver { receiver: account }.into()
 251	            );
 252	        }
 253	
 254	        self.safe_erc20.safe_transfer_from(
 255	            self.underlying(),
 256	            sender,
 257	            contract_address,
 258	            value,
 259	        )?;
 260	
 261	        erc20._mint(account, value)?;
 262	
 263	        Ok(true)
 264	    }
