 269	        &mut self,
 270	        account: Address,
 271	        value: U256,
 272	        erc20: &mut Erc20,
 273	    ) -> Result<bool, Error> {
 274	        if account == self.vm().contract_address() {
 275	            return Err(
 276	                erc20::ERC20InvalidReceiver { receiver: account }.into()
 277	            );
 278	        }
 279	
 280	        erc20._burn(self.vm().msg_sender(), value)?;
 281	
 282	        self.safe_erc20.safe_transfer(self.underlying(), account, value)?;
 283	
 284	        Ok(true)
