 251	            );
 252	        }
 253	
 254	        self.safe_erc20.safe_transfer_from(
 255	            self.underlying(),
 256	            sender,
 257	            contract_address,
 258	            value,
 259	        )?;
 260	
 261	        erc20._mint(account, value)?;
 262	
 263	        Ok(true)
 264	    }
