   392	    #[must_use]
   393	    #[allow(clippy::missing_panics_doc)]
   394	    pub const fn mul(&self, rhs: &Self) -> Self {
   395	        let (low, high) = self.widening_mul(rhs);
   396	        assert!(high.eq(&Uint::<N>::ZERO), "overflow on multiplication");
