 89	impl Capped {
 90	    /// Checks whether increasing the current supply by `increase` stays
 91	    /// within the configured cap.
 92	    ///
 93	    /// Call this before minting in the consuming contract. Including
 94	    /// [`Capped`] does not automatically route an
 95	    /// [`Erc20`](crate::token::erc20::Erc20) mint through this
 96	    /// check.
 97	    ///
 98	    /// # Errors
 99	    ///
100	    /// * [`Error::ExceededCap`] - If the resulting supply is greater than the
101	    ///   configured cap.
102	    pub fn _check_cap(
103	        &self,
104	        current_supply: U256,
105	        increase: U256,
106	    ) -> Result<(), Error> {
107	        let increased_supply = current_supply
108	            .checked_add(increase)
109	            .expect("increased supply should not overflow U256");
110	        let cap = self.cap.get();
111	
112	        if increased_supply > cap {
113	            return Err(Error::ExceededCap(ERC20ExceededCap {
114	                increased_supply,
115	                cap,
116	            }));
117	        }
118	
119	        Ok(())
120	    }
121	}
