    12	/// This trait provides a fallback function that delegates all calls to another
    13	/// contract using the Stylus [`delegate_call`][delegate_call] function. We
    14	/// refer to the second contract as the _implementation_ behind the proxy, and
    15	/// it has to be specified by overriding the virtual [`IProxy::implementation`]
    16	/// function.
    17	///
    18	/// Additionally, delegation to the implementation can be triggered manually
    19	/// through the [`IProxy::do_fallback`] function, or to a different contract
    20	/// through the [`IProxy::delegate`] function.
    21	///
    22	/// The success and return data of the delegated call will be returned back
    23	/// to the caller of the proxy.
    24	///
    25	/// # Safety
    26	///
    27	/// This trait is unsafe to implement because it uses the `unsafe`
    28	/// [`delegate_call`][delegate_call] function.
    29	///
    30	/// The caller must ensure that `self` is a valid contract storage context.
    31	///
    32	/// The caller must ensure that the implementation contract is a valid contract
    33	/// address.
    34	///
    35	/// [delegate_call]: stylus_sdk::call::delegate_call
    36	pub unsafe trait IProxy:
    37	    TopLevelStorage + HostAccess<Host = VM> + Sized
    38	{
    39	    /// Delegates the current call to [`IProxy::implementation`].
    40	    ///
    41	    /// This function does not return to its internal call site, it will
    42	    /// return directly to the external caller.
    43	    ///
    44	    /// # Arguments
    45	    ///
    46	    /// * `&mut self` - Write access to the contract's state.
    47	    /// * `implementation` - The address of the implementation contract.
    48	    /// * `calldata` - The calldata to delegate to the implementation contract.
    49	    ///
    50	    /// # Errors
    51	    ///
    52	    /// Returns a [`stylus_sdk::stylus_core::calls::errors::Error`] if the delegate call fails. This
    53	    /// error may represent:
    54	    /// * A revert from the implementation  containing the revert data.
    55	    /// * Failure to decode the return data from the implementation contract.
    56	    /// * Other low-level call failures as defined by the Stylus SDK.
    57	    #[allow(clippy::missing_safety_doc)]
    58	    unsafe fn delegate(
    59	        &mut self,
    60	        implementation: Address,
    61	        calldata: &[u8],
    62	    ) -> Result<Vec<u8>, stylus_sdk::stylus_core::calls::errors::Error> {
    63	        let vm = self.vm().clone();
    64	        call::delegate_call(
    65	            &vm,
    66	            Call::new_mutating(self),
    67	            implementation,
    68	            calldata,
    69	        )
    70	    }
    71	
    72	    /// This is a virtual function that should be overridden so it
    73	    /// returns the address to which the fallback function and
    74	    /// [`IProxy::do_fallback`] should delegate.
    75	    ///
    76	    /// # Arguments
    77	    ///
    78	    /// * `&self` - Read access to the contract's state.
    79	    ///
    80	    /// # Errors
    81	    ///
    82	    /// Implementing contracts should define their own error types for this
    83	    /// function. Typically, errors may include:
    84	    /// * The implementation address is invalid (e.g., not a contract).
    85	    /// * The implementation is not a contract.
    86	    ///
    87	    /// The error should be encoded as a `Vec<u8>`.
    88	    fn implementation(&self) -> Result<Address, Vec<u8>>;
    89	
    90	    /// Fallback function that delegates calls to the address returned
    91	    /// by [`IProxy::implementation`]. Will run if no other function in the
    92	    /// contract matches the call data.
    93	    ///
    94	    /// # Arguments
    95	    ///
    96	    /// * `&mut self` - Write access to the contract's state.
    97	    /// * `calldata` - The calldata to delegate to the implementation contract.
    98	    ///
    99	    /// # Errors
   100	    ///
   101	    /// Implementing contracts should define their own error types for this
   102	    /// function. Typically, errors may include:
   103	    /// * The implementation address is invalid (e.g., not a contract).
   104	    /// * The implementation is not a contract.
   105	    /// * The implementation reverted with a reason.
   106	    ///
   107	    /// The error should be encoded as a `Vec<u8>`.
   108	    #[allow(clippy::missing_safety_doc)]
   109	    unsafe fn do_fallback(
   110	        &mut self,
   111	        calldata: &[u8],
   112	    ) -> Result<Vec<u8>, Vec<u8>> {
   113	        Ok(self.delegate(self.implementation()?, calldata)?)
   114	    }
   115	}
