139	/// Interface for [`Erc20Permit`]
140	#[allow(missing_docs)]
141	#[public]
142	pub trait IErc20Permit: INonces {
143	    /// The error type associated to this interface.
144	    type Error: Into<alloc::vec::Vec<u8>>;
145	
146	    // Calculated manually to include [`INonces::nonces`].
147	    /// Solidity interface id associated with [`IErc20Permit`] trait.
148	    /// Computed as a XOR of selectors for each function in the trait.
149	    #[must_use]
150	    fn interface_id() -> B32
151	    where
152	        Self: Sized,
153	    {
154	        B32::new(function_selector!("DOMAIN_SEPARATOR",))
155	            ^ B32::new(function_selector!("nonces", Address,))
156	            ^ B32::new(function_selector!(
157	                "permit", Address, Address, U256, U256, U8, B256, B256
158	            ))
159	    }
160	
161	    /// Returns the domain separator used in the encoding of the signature for
162	    /// [`Self::permit`], as defined by EIP712.
163	    ///
164	    /// NOTE: The implementation should use `#[selector(name =
165	    /// "DOMAIN_SEPARATOR")]` to match Solidity's camelCase naming
220	    pub fn domain_separator(&self) -> B256 {
221	        self.eip712.domain_separator_v4()
222	    }
223	
224	    /// See [`IErc20Permit::permit`].
225	    #[allow(clippy::too_many_arguments, clippy::missing_errors_doc)]
226	    pub fn permit(
227	        &mut self,
228	        owner: Address,
229	        spender: Address,
230	        value: U256,
231	        deadline: U256,
232	        v: u8,
233	        r: B256,
234	        s: B256,
235	        erc20: &mut Erc20,
236	        nonces: &mut Nonces,
237	    ) -> Result<(), Error> {
238	        if U256::from(self.vm().block_timestamp()) > deadline {
239	            return Err(ERC2612ExpiredSignature { deadline }.into());
240	        }
241	
242	        let nonce = nonces.nonces(owner);
243	        let struct_hash = keccak256(StructHashTuple::abi_encode(&(
244	            PERMIT_TYPEHASH,
245	            owner,
246	            spender,
247	            value,
248	            nonce,
249	            deadline,
250	        )));
251	
252	        let hash: B256 = self.eip712.hash_typed_data_v4(struct_hash);
253	
254	        let signer: Address = self.ec_recover(hash, v, r, s)?;
255	
256	        if signer != owner {
257	            return Err(ERC2612InvalidSigner { signer, owner }.into());
258	        }
259	
260	        erc20._approve(owner, spender, value, true)?;
261	        nonces.use_nonce(owner);
262	
263	        Ok(())
264	    }
265	}
