159	#[public]
160	impl IOwnable2Step for Ownable2Step {
161	    type Error = ownable::Error;
162	
163	    fn owner(&self) -> Address {
164	        self.ownable.owner()
165	    }
166	
167	    fn pending_owner(&self) -> Address {
168	        self.pending_owner.get()
169	    }
170	
171	    fn transfer_ownership(
172	        &mut self,
173	        new_owner: Address,
174	    ) -> Result<(), ownable::Error> {
175	        self.ownable.only_owner()?;
176	        self.pending_owner.set(new_owner);
177	
178	        let current_owner = self.owner();
179	        self.vm().log(OwnershipTransferStarted {
180	            previous_owner: current_owner,
181	            new_owner,
182	        });
183	        Ok(())
184	    }
185	
186	    fn accept_ownership(&mut self) -> Result<(), ownable::Error> {
187	        let sender = self.vm().msg_sender();
188	        let pending_owner = self.pending_owner();
189	        if sender != pending_owner {
190	            return Err(ownable::Error::UnauthorizedAccount(
191	                ownable::OwnableUnauthorizedAccount { account: sender },
192	            ));
193	        }
194	        self._transfer_ownership(sender);
195	        Ok(())
196	    }
197	
198	    fn renounce_ownership(&mut self) -> Result<(), ownable::Error> {
199	        self.ownable.only_owner()?;
200	        self._transfer_ownership(Address::ZERO);
201	        Ok(())
202	    }
203	}
