171	    fn transfer_ownership(
172	        &mut self,
173	        new_owner: Address,
174	    ) -> Result<(), ownable::Error> {
175	        self.ownable.only_owner()?;
176	        self.pending_owner.set(new_owner);
177	
178	        let current_owner = self.owner();
179	        self.vm().log(OwnershipTransferStarted {
180	            previous_owner: current_owner,
181	            new_owner,
182	        });
183	        Ok(())
184	    }
