205	impl Ownable2Step {
206	    /// Transfers ownership of the contract to a new account (`new_owner`) and
207	    /// sets [`Self::pending_owner`] to [`Address::ZERO`] to avoid situations
208	    /// where the transfer has been completed or the current owner renounces,
209	    /// but [`Self::pending_owner`] can still accept ownership.
210	    ///
211	    /// Internal function without access restriction.
212	    ///
213	    /// # Arguments
214	    ///
215	    /// * `&mut self` - Write access to the contract's state.
216	    /// * `new_owner` - Account that's gonna be the next owner.
217	    ///
218	    /// # Events
219	    ///
220	    /// * [`crate::access::ownable::OwnershipTransferred`].
221	    fn _transfer_ownership(&mut self, new_owner: Address) {
222	        self.pending_owner.set(Address::ZERO);
223	        self.ownable._transfer_ownership(new_owner);
224	    }
225	}
