251	/// In "Ed25519" format, the curve point `(x,y)` is
252	/// determined by the y-coordinate and the sign of `x`.
253	///
254	/// The first 255 bits of a `CompressedEdwardsY` represent the `y`-coordinate.
255	/// The high bit of the 32nd byte gives the sign of `x`.
256	#[derive(Copy, Clone, Hash)]
257	pub struct CompressedPointY([u8; 32]);
