275	impl From<AffinePoint> for CompressedPointY {
276	    fn from(point: AffinePoint) -> Self {
277	        let mut s: [u8; 32] = point
278	            .y
279	            .into_bigint()
280	            .into_bytes_le()
281	            .try_into()
282	            .expect("Y coordinate should be 32 bytes");
283	
284	        // Using the last bit to encode `x`, since the base field modulus is
285	        // asserted to have a spare bit.
286	        let is_odd = point.x.into_bigint().is_odd();
287	        s[31] ^= u8::from(is_odd) << 7;
288	
289	        CompressedPointY(s)
290	    }
291	}
