 46	pub struct Poseidon2<P: PoseidonParams<F>, F: PrimeField> {
 47	    phantom: core::marker::PhantomData<P>,
 48	    state: Box<[F]>,
 49	    mode: Mode,
 50	    index: usize,
 51	}
