293	/// Ed25519 signature representation.
294	///
295	/// Signature verification libraries are expected to reject invalid
296	/// field elements at the time a signature is verified.
297	#[derive(Copy, Clone, Eq, PartialEq)]
298	pub struct Signature {
299	    /// `R` is an `EdwardsPoint`, formed by using an hash function with
300	    /// `512-bits` output to produce the digest of:
301	    ///
302	    /// * the nonce half of the `ExpandedSecretKey`, and
303	    /// * the message to be signed.
304	    ///
305	    /// This digest is then interpreted as a `Scalar` and reduced into an
306	    /// element in ℤ/lℤ.  The scalar is then multiplied by the distinguished
307	    /// basepoint to produce `R`, and `EdwardsPoint`.
308	    pub R: ProjectivePoint,
309	
310	    /// `s` is a `Scalar`, formed by using a hash function with `512-bits`
311	    /// output to produce the digest of:
312	    ///
313	    /// * the `r` portion of this `Signature`,
314	    /// * the `PublicKey` which should be used to verify this `Signature`, and
315	    /// * the message to be signed.
316	    ///
317	    /// This digest is then interpreted as a `Scalar` and reduced into an
318	    /// element in ℤ/lℤ.
319	    pub s: Scalar,
320	}
321	
322	impl Signature {
323	    /// Converts the signature to a 64-byte array.
324	    ///
325	    /// The first 32 bytes contain the compressed encoding of the `R` value.
326	    /// The last 32 bytes contain the canonical encoding of the `s` scalar.
327	    #[must_use]
328	    pub fn to_bytes(&self) -> [u8; SIGNATURE_LENGTH] {
329	        let mut bytes = [0u8; 64];
330	
331	        // Get the compressed representation of R
332	        let r_compressed = CompressedPointY::from(self.R.into_affine());
333	        bytes[..32].copy_from_slice(r_compressed.as_ref());
334	
335	        // Get the little-endian byte representation of s
336	        let s_bytes = self.s.into_bigint().into_bytes_le();
337	        bytes[32..].copy_from_slice(&s_bytes[..32]);
338	
339	        bytes
340	    }
341	
342	    /// Construct a signature from affine point `R` and scalar `s`.
343	    #[must_use]
344	    pub fn from_affine_R_s(R: AffinePoint, s: Scalar) -> Self {
345	        Signature { R: R.into(), s }
346	    }
347	}
