418	    /// Convert the [`VerifyingKey`] to a compressed byte representation.
419	    #[inline]
420	    #[must_use]
421	    pub fn to_bytes(&self) -> PublicKey {
422	        CompressedPointY::from(self.point.into_affine()).into()
423	    }
