   541	    /// Performs an implementation upgrade with a security check for UUPS
   542	    /// proxies, and additional setup call.
   543	    ///
   544	    /// As a security check, [`IErc1822Proxiable::proxiable_uuid`] is invoked
   545	    /// in the new implementation, and the return value is expected to be the
   546	    /// implementation slot in ERC-1967.
   547	    ///
   548	    /// # Arguments
   549	    ///
   550	    /// * `&mut self` - Write access to the contract's state.
   551	    /// * `new_implementation` - The address of the new implementation.
   552	    /// * `data` - The data to pass to the new implementation.
   553	    ///
   554	    /// # Errors
   555	    ///
   556	    /// * [`Error::InvalidImplementation`] - If the new implementation doesn't
   557	    ///   support the required interface or is invalid.
   558	    /// * [`Error::UnsupportedProxiableUUID`] - If the new implementation
   559	    ///   returns an unsupported UUID.
   560	    /// * [`Error::NonPayable`] - If the upgrade function receives ETH but is
   561	    ///   not designed to handle it.
   562	    /// * [`Error::EmptyCode`] - If there's no code at the new implementation
   563	    ///   address.
   564	    /// * [`Error::FailedCall`] - If the [`delegate_call`][delegate_call] to the
   565	    ///   new implementation fails.
   566	    /// * [`Error::FailedCallWithReason`] - If the
   567	    ///   [`stylus_sdk::call::delegate_call`] fails with a specific reason.
   568	    ///
   569	    /// # Events
   570	    ///
   571	    /// * [`crate::proxy::erc1967::Erc1967Proxy::Upgraded`]: Emitted when the
   572	    ///   implementation is upgraded.
   573	    ///
   574	    /// [delegate_call]: stylus_sdk::call::delegate_call
   575	    fn _upgrade_to_and_call_uups(
   576	        &mut self,
   577	        new_implementation: Address,
   578	        data: &Bytes,
   579	    ) -> Result<(), Error> {
   580	        let slot = Erc1822ProxiableInterface::new(new_implementation)
   581	            .proxiable_uuid(self.vm(), Call::new())
   582	            .map_err(|_e| {
   583	                Error::InvalidImplementation(ERC1967InvalidImplementation {
   584	                    implementation: new_implementation,
   585	                })
   586	            })?;
   587	
   588	        if slot == IMPLEMENTATION_SLOT {
   589	            Erc1967Utils::upgrade_to_and_call(self, new_implementation, data)
   590	                .map_err(Error::from)
   591	        } else {
   592	            Err(Error::UnsupportedProxiableUUID(UUPSUnsupportedProxiableUUID {
   593	                slot,
   594	            }))
   595	        }
   596	    }
   597	}
