320	    ///
321	    /// # Arguments
322	    ///
323	    /// * `&mut self` - Write access to the contract's state.
324	    /// * `account` - The account to mint tokens to.
325	    /// * `erc20` - Write access to an [`Erc20`] contract.
326	    ///
327	    /// # Errors
328	    ///
329	    /// * [`Error::InvalidUnderlying`]  - If the external call for
330	    ///   [`IErc20::balance_of`] fails.
331	    /// * [`Error::InvalidReceiver`] - If the `account` address is
332	    ///   [`Address::ZERO`].
333	    ///
334	    /// # Panics
335	    ///
336	    /// * If the underlying balance is less than the [`IErc20::total_supply`].
337	    pub fn _recover(
338	        &mut self,
339	        account: Address,
340	        erc20: &mut Erc20,
341	    ) -> Result<U256, Error> {
342	        let contract_address = self.vm().contract_address();
343	
344	        let underlying_token = Erc20Interface::new(self.underlying());
345	
346	        let underlying_balance = underlying_token
347	            .balance_of(self.vm(), Call::new(), contract_address)
348	            .map_err(|_| ERC20InvalidUnderlying { token: contract_address })?;
349	
350	        let value = underlying_balance
351	            .checked_sub(erc20.total_supply())
352	            .expect("underlying balance should be greater than the `IErc20::total_supply`");
353	
354	        if value > U256::ZERO {
355	            erc20._mint(account, value)?;
356	        }
357	
358	        Ok(value)
359	    }
