 15	struct EddsaExample;
 16	
 17	fn has_canonical_encoding(
 18	    verifying_key: [alloy_primitives::U256; 2],
 19	    signature: [alloy_primitives::U256; 3],
 20	) -> bool {
 21	    let base_modulus: alloy_primitives::U256 =
 22	        Curve25519FqParam::MODULUS.into();
 23	    let scalar_modulus: alloy_primitives::U256 =
 24	        Curve25519FrParam::MODULUS.into();
 25	
 26	    verifying_key.into_iter().all(|coordinate| coordinate < base_modulus)
 27	        && signature[..2].iter().all(|coordinate| *coordinate < base_modulus)
 28	        && signature[2] < scalar_modulus
 29	}
 30	
 31	#[public]
 32	impl EddsaExample {
 33	    /// Verification api is slightly different from canonical implementation
 34	    /// missing compressed points. Coordinates must be less than the base-field
 35	    /// modulus, and `s` must be less than the scalar-field modulus.
 36	    fn verify(
 37	        &self,
 38	        verifying_key: [alloy_primitives::U256; 2],
 39	        signature: [alloy_primitives::U256; 3],
 40	        message: Bytes,
 41	    ) -> bool {
 42	        if !has_canonical_encoding(verifying_key, signature) {
 43	            return false;
 44	        }
 45	
 46	        let verifying_key = VerifyingKey::from_affine(AffinePoint {
 47	            x: Fp256::<Curve25519FqParam>::from_bigint(verifying_key[0].into()),
 48	            y: Fp256::<Curve25519FqParam>::from_bigint(verifying_key[1].into()),
 49	        });
 50	
 51	        let signature = Signature::from_affine_R_s(
 52	            AffinePoint {
 53	                x: Fp256::<Curve25519FqParam>::from_bigint(signature[0].into()),
 54	                y: Fp256::<Curve25519FqParam>::from_bigint(signature[1].into()),
 55	            },
 56	            Scalar::from_bigint(signature[2].into()),
 57	        );
 58	
 59	        verifying_key.is_valid(&message, &signature)
 60	    }
 61	}
