110	impl UpgradeableBeacon {
111	    /// Sets the address of the initial implementation, and the initial owner
112	    /// who can upgrade the beacon.
113	    ///
114	    /// # Arguments
115	    ///
116	    /// * `&mut self` - Write access to the contract's state.
117	    /// * `implementation` - The address of the initial implementation.
118	    ///
119	    /// # Errors
120	    ///
121	    /// * [`Error::InvalidImplementation`] - If `implementation` is not a
122	    ///   contract.
123	    /// * [`Error::UnauthorizedAccount`] - If the caller is not the owner.
124	    ///
125	    /// # Events
126	    ///
127	    /// * [`Upgraded`].
128	    #[constructor]
129	    pub fn constructor(
130	        &mut self,
131	        implementation: Address,
132	        initial_owner: Address,
133	    ) -> Result<(), Error> {
134	        self.ownable.constructor(initial_owner)?;
135	        self.set_implementation(implementation)?;
136	        Ok(())
137	    }
138	
139	    /// Upgrades the beacon to a new implementation.
140	    ///
141	    /// # Arguments
142	    ///
143	    /// * `&mut self` - Write access to the contract's state.
144	    /// * `new_implementation` - The address of the new implementation.
145	    ///
146	    /// # Errors
147	    ///
148	    /// * [`Error::InvalidImplementation`] - If `new_implementation` is not a
149	    ///   contract.
150	    /// * [`Error::UnauthorizedAccount`] - If the caller is not the owner.
151	    ///
152	    /// # Events
153	    ///
154	    /// * [`Upgraded`].
155	    pub fn upgrade_to(
156	        &mut self,
157	        new_implementation: Address,
158	    ) -> Result<(), Error> {
159	        self.ownable.only_owner()?;
160	        self.set_implementation(new_implementation)
161	    }
162	
163	    /// Upgrades the beacon to a new implementation.
164	    ///
165	    /// # Arguments
166	    ///
167	    /// * `&mut self` - Write access to the contract's state.
168	    /// * `new_implementation` - The address of the new implementation.
169	    ///
170	    /// # Errors
171	    ///
172	    /// * [`Error::InvalidImplementation`] - If `new_implementation` is not a
173	    ///   contract.
174	    ///
175	    /// # Events
176	    ///
177	    /// * [`Upgraded`].
178	    fn set_implementation(
179	        &mut self,
180	        new_implementation: Address,
181	    ) -> Result<(), Error> {
182	        if self.vm().code_size(new_implementation) == 0 {
183	            return Err(Error::InvalidImplementation(
184	                BeaconInvalidImplementation {
185	                    implementation: new_implementation,
186	                },
187	            ));
188	        }
189	        self.implementation.set(new_implementation);
190	        self.vm().log(Upgraded { implementation: new_implementation });
191	        Ok(())
192	    }
193	}
