   107	
   108	            #[doc = concat!("Solidity interface id associated with ", stringify!(#name), " trait.")]
   109	            #[doc = "Computed as a XOR of selectors for each function in the trait."]
   110	            fn interface_id() -> alloy_primitives::aliases::B32
   111	            where
   112	                Self: Sized,
