330	    pub(crate) fn _allowance_after_spending(
331	        &self,
332	        owner: Address,
333	        spender: Address,
334	        value: U256,
335	    ) -> Result<Option<U256>, Error> {
336	        let current_allowance = self.allowance(owner, spender);
337	        if current_allowance == U256::MAX {
338	            return Ok(None);
339	        }
340	        if current_allowance < value {
341	            return Err(Error::InsufficientAllowance(
342	                ERC20InsufficientAllowance {
343	                    spender,
344	                    allowance: current_allowance,
345	                    needed: value,
346	                },
347	            ));
348	        }
349	
350	        // `_spend_allowance` historically reports insufficient allowance
351	        // before `_approve` reports invalid owner or spender addresses.
352	        if owner.is_zero() {
353	            return Err(Error::InvalidApprover(ERC20InvalidApprover {
354	                approver: Address::ZERO,
355	            }));
356	        }
357	        if spender.is_zero() {
358	            return Err(Error::InvalidSpender(ERC20InvalidSpender {
359	                spender: Address::ZERO,
360	            }));
361	        }
362	
363	        Ok(Some(current_allowance - value))
364	    }
