 33	macro_rules! define_checkpoint_size {
 34	    ($name:ident, $key_bits:expr, $value_bits:expr) => {
 35	        #[doc = "Size of checkpoint storage contract with"]
 36	        #[doc = stringify!($key_bits)]
 37	        #[doc = "bit key and "]
 38	        #[doc = stringify!($value_bits)]
 39	        #[doc = "bit value."]
 40	        pub struct $name;
 41	
 42	        impl Size for $name {
 43	            type Key = stylus_sdk::alloy_primitives::Uint<
 44	                $key_bits,
 45	                { usize::div_ceil($key_bits, 64) },
 46	            >;
 47	            type KeyStorage = stylus_sdk::storage::StorageUint<
 48	                $key_bits,
 49	                { usize::div_ceil($key_bits, 64) },
