 51	            type Value = stylus_sdk::alloy_primitives::Uint<
 52	                $value_bits,
 53	                { usize::div_ceil($value_bits, 64) },
 54	            >;
 55	            type ValueStorage = stylus_sdk::storage::StorageUint<
 56	                $value_bits,
 57	                { usize::div_ceil($value_bits, 64) },
 58	            >;
 59	        }
 60	    };
