363	    /// Verify a signature on a message with this keypair's public key.
364	    #[must_use]
365	    pub fn is_valid(&self, message: &[u8], signature: &Signature) -> bool {
366	        if self.point.z.is_zero() || signature.R.z.is_zero() {
367	            return false;
368	        }
369	
370	        let public_key = self.point.into_affine();
371	        let R = signature.R.into_affine();
372	
373	        if public_key.is_zero()
374	            || R.is_zero()
375	            || !public_key.is_on_curve()
376	            || !R.is_on_curve()
377	            || !public_key.is_in_prime_order_subgroup()
378	            || !R.is_in_prime_order_subgroup()
379	        {
380	            return false;
381	        }
382	
383	        // Rebuild projective points from their validated affine coordinates.
384	        // This discards any inconsistent T coordinate supplied by callers.
385	        let verifying_key = Self::from_affine(public_key);
386	        let signature = Signature::from_affine_R_s(R, signature.s);
387	
388	        let expected_r = verifying_key.compute_R(&signature, message);
389	        expected_r == signature.R
390	    }
