        &mut self,
        owner: Address,
        spender: Address,
        value: U256,
    ) -> Result<(), Error> {
        let remaining_allowance =
            self._allowance_after_spending(owner, spender, value)?;
        self._write_spent_allowance(owner, spender, remaining_allowance)
    }
}

