    /// * `data` - Additional data with no specified format, sent in the call to
    ///   `IERC1363`.
    ///
    /// # Errors
    ///
    /// * [`Error::SafeErc20FailedOperation`] - If `token` has no code, the
    ///   external call fails, or the call returns `false`.
    fn transfer_from_and_call_relaxed(
        &mut self,
        token: Address,
        from: Address,
        to: Address,
        value: U256,
        data: Bytes,
    ) -> Result<(), Self::Error>;

