    ///
    /// # Errors
    ///
    /// * [`Error::SafeErc20FailedOperation`] - If `token` has no code, the
    ///   external call fails, or the call returns `false`.
    fn call_optional_return(
        &mut self,
        token: Address,
        call: &impl SolCall,
    ) -> Result<(), Error> {
        if self.vm().code_size(token) == 0 {
            return Err(Error::SafeErc20FailedOperation(
                SafeErc20FailedOperation { token },
            ));
        }

        let result = unsafe {
            RawCall::new(self.vm())
                .limit_return_data(0, BOOL_TYPE_SIZE)
                .flush_storage_cache()
                .call(token, &call.abi_encode())
        };

        match result {
            Ok(data)
                if data.is_empty()
                    || Bool::abi_decode(&data).is_ok_and(|success| success) =>
            {
                Ok(())
            }
            _ => Err(SafeErc20FailedOperation { token }.into()),
        }
    }

    /// Returns the remaining number of ERC-20 tokens that `spender`
    /// will be allowed to spend on behalf of an owner.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `token` - Address of the ERC-20 token contract.
    /// * `spender` - Account that will spend the tokens.
    ///
    /// # Errors
    ///
    /// * [`Error::SafeErc20FailedOperation`] - If the contract fails to read
    ///   `spender`'s allowance.
    fn allowance(
        &self,
        token: Address,
        spender: Address,
    ) -> Result<U256, Error> {
        if self.vm().code_size(token) == 0 {
            return Err(SafeErc20FailedOperation { token }.into());
        }

        let erc20 = Erc20Interface::new(token);
        erc20
            .allowance(
                self.vm(),
                Call::new(),
                self.vm().contract_address(),
                spender,
            )
            .map_err(|_e| {
                Error::SafeErc20FailedOperation(SafeErc20FailedOperation {
                    token,
                })
            })
    }
}

