impl Erc20 {
    /// Validates a proposed allowance spend without changing storage.
    ///
    /// The returned value is `None` for an infinite allowance and otherwise
    /// contains the remaining allowance to write after the associated token
    /// operation succeeds.
    pub(crate) fn _allowance_after_spending(
        &self,
        owner: Address,
        spender: Address,
        value: U256,
    ) -> Result<Option<U256>, Error> {
        let current_allowance = self.allowance(owner, spender);
        if current_allowance == U256::MAX {
            return Ok(None);
        }
        if current_allowance < value {
            return Err(Error::InsufficientAllowance(
                ERC20InsufficientAllowance {
                    spender,
                    allowance: current_allowance,
                    needed: value,
                },
            ));
        }

        // `_spend_allowance` historically reports insufficient allowance
        // before `_approve` reports invalid owner or spender addresses.
        if owner.is_zero() {
            return Err(Error::InvalidApprover(ERC20InvalidApprover {
                approver: Address::ZERO,
            }));
        }
        if spender.is_zero() {
            return Err(Error::InvalidSpender(ERC20InvalidSpender {
                spender: Address::ZERO,
            }));
        }

        Ok(Some(current_allowance - value))
    }

    /// Writes a previously validated allowance remainder after the associated
    /// token operation succeeds.
    pub(crate) fn _write_spent_allowance(
        &mut self,
        owner: Address,
        spender: Address,
        remaining_allowance: Option<U256>,
    ) -> Result<(), Error> {
        if let Some(allowance) = remaining_allowance {
            self._approve(owner, spender, allowance, false)?;
        }
        Ok(())
    }

    /// Sets a `value` number of tokens as the allowance of `spender` over the
    /// caller's tokens.
    ///
    /// Returns a boolean value indicating whether the operation succeeded.
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `owner` - Account that owns the tokens.
    /// * `spender` - Account that will spend the tokens.
    /// * `emit_event` - Emit an [`Approval`] event flag.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSpender`] - If the `spender` address is
    ///   [`Address::ZERO`].
    ///
    /// # Events
    ///
    /// * [`Approval`].
    fn _approve(
        &mut self,
        owner: Address,
        spender: Address,
        value: U256,
        emit_event: bool,
    ) -> Result<bool, Error> {
        if owner.is_zero() {
            return Err(Error::InvalidApprover(ERC20InvalidApprover {
                approver: Address::ZERO,
            }));
        }

        if spender.is_zero() {
            return Err(Error::InvalidSpender(ERC20InvalidSpender {
                spender: Address::ZERO,
            }));
        }

        self.allowances.setter(owner).insert(spender, value);
        if emit_event {
            self.vm().log(Approval { owner, spender, value });
        }
        Ok(true)
    }

    /// Internal implementation of transferring tokens between two accounts.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to transfer tokens from.

impl SafeErc20 {
    /// Imitates a Stylus high-level call, relaxing the requirement on the
    /// return value: if data is returned, it must not be `false`, otherwise
    /// calls are assumed to be successful.
    ///
    /// # Arguments
    ///
    /// * `token` - Address of the ERC-20 token contract.
    /// * `call` - [`IErc20`] call that implements [`SolCall`] trait.
    ///
    /// # Errors
    ///
    /// * [`Error::SafeErc20FailedOperation`] - If `token` has no code, the
    ///   external call fails, or the call returns `false`.
    fn call_optional_return(
        &mut self,
        token: Address,
        call: &impl SolCall,
    ) -> Result<(), Error> {
        if self.vm().code_size(token) == 0 {
            return Err(Error::SafeErc20FailedOperation(
                SafeErc20FailedOperation { token },
            ));
        }

        let result = unsafe {
            RawCall::new(self.vm())
                .limit_return_data(0, BOOL_TYPE_SIZE)
                .flush_storage_cache()
                .call(token, &call.abi_encode())
        };

        match result {
            Ok(data)
                if data.is_empty()
                    || Bool::abi_decode(&data).is_ok_and(|success| success) =>
            {
                Ok(())
            }
            _ => Err(SafeErc20FailedOperation { token }.into()),
        }
    }

    /// Returns the remaining number of ERC-20 tokens that `spender`
    /// will be allowed to spend on behalf of an owner.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `token` - Address of the ERC-20 token contract.
    /// * `spender` - Account that will spend the tokens.
    ///
    /// # Errors
    ///
    /// * [`Error::SafeErc20FailedOperation`] - If the contract fails to read
    ///   `spender`'s allowance.
    fn allowance(
        &self,
        token: Address,
        spender: Address,
    ) -> Result<U256, Error> {
        if self.vm().code_size(token) == 0 {
            return Err(SafeErc20FailedOperation { token }.into());
        }

        let erc20 = Erc20Interface::new(token);
        erc20
            .allowance(
                self.vm(),
                Call::new(),
                self.vm().contract_address(),
                spender,
            )
            .map_err(|_e| {
                Error::SafeErc20FailedOperation(SafeErc20FailedOperation {
                    token,
                })
            })
    }
}

